programs.sol:
"""Short Latin chunks used as symbols rather than ordinary words.

Approximate negative responses to two-letter mathematical symbols, geometric
labels and literal letter sequences, plus short chunks of encoded strings.
Ordinary prose is left near zero. Additive strengths are fitted on training text.
Only a bounded recent text window is carried, reset at document boundaries.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
SYMBOLS = re.compile(r'[=+*/^<>]|\\(?:frac|sqrt|cdot|times)|[²³∑∫]')
GEOMETRY = re.compile(
    r'triangle|midpoint|centroid|parallelogram|vert(?:ex|ices)|segment|quadrilateral',
    re.I,
)
ALGEBRA = re.compile(r'equation|polynomial|coefficient|variable|algebra', re.I)


@lru_cache(maxsize=4096)
def frequency(letters):
    return zipf_frequency(letters.lower(), 'en')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history, previous = '', ''
    else:
        _, history, previous = carry
    token = prefix.token_strings[-1]
    state = (document, (history + token)[-512:], token)
    bare = token.strip()
    letters = re.sub('[^A-Za-z]', '', bare)
    pair = len(letters) == 2 and not re.search(
        '[A-Za-z].*[^A-Za-z].*[A-Za-z]', bare
    )
    partial = bool(re.fullmatch('[A-Za-z]', bare)) and bool(
        re.fullmatch(' ?[A-Za-z]', previous)
    ) and not token[0].isspace()
    if partial:
        letters = previous.strip() + bare
        pair = True
    if not (pair or (len(letters) in (1, 3) and bare.isascii())):
        return state, -0.002

    recent = history[-96:]
    math = bool(SYMBOLS.search(recent))
    geometry = bool(GEOMETRY.search(history))
    algebra = bool(ALGEBRA.search(history))
    separated = not (
        previous[-1:].isalpha() and not token[:1].isspace()
    )
    value = -0.002
    if len(letters) == 2:
        rare = frequency(letters) < 4.8
        coordinate = any(c.lower() in 'xyz' for c in letters)
        if rare:
            if separated and math:
                value -= 0.157
                if algebra:
                    value -= 0.783
                # Coordinate variables often form products such as ax or xy.
                if letters[-1].lower() == 'x':
                    value -= 0.817
                elif letters[-1].lower() in 'yz':
                    value -= 0.229
            if geometry and letters.isupper():
                value -= 1.415
            if math and re.search('[=+*/^(]$', previous):
                value -= 0.296
            if previous[-1:].isdigit() and re.search(
                r'0x|[a-f][0-9][a-f0-9]{3}|[0-9][a-f][0-9]', recent
            ):
                value -= 0.666
        if coordinate and separated:
            if math:
                value -= 0.053
            if algebra:
                value -= 0.311
        if re.search(r'letters? (?:picked|chosen)|prob of sequence', history, re.I):
            value -= 0.376

    # Short pieces of long mixed-case alphanumeric/encoded strings.
    if len(letters) >= 2:
        run = re.search('[A-Za-z0-9+/]*$', history).group()
        digits = sum(c.isdigit() for c in run)
        switches = sum(a.islower() != b.islower()
                       for a, b in zip(run, run[1:])
                       if a.isalpha() and b.isalpha())
        if sum(c.isupper() for c in recent) > 25:
            if sum(c.isdigit() for c in recent) > 10:
                value -= 0.470
        if len(run) > 20 and digits > 3 and switches > 5:
            value -= 1.059
    return state, value

programs.haiku:
"""Variant: adds a stronger value for a letter label right after '+' (polynomial terms)."""
import string

READS = ()
LATIN = frozenset(string.ascii_letters)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    name = text.strip()
    spaced = text[:1] == " "
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if name and all(c in LATIN for c in name):
        if len(name) == 2:
            if prev == "+" and not spaced:
                return carry, -0.5
            if name.isupper():
                return carry, -0.10
            if spaced:
                return carry, -0.01
            return carry, -0.03
        if len(name) == 1 and not spaced and name.islower():
            return carry, -0.02
    if name == "··":
        return carry, 0.8
    return carry, 0.0

programs.sol:
"""Detect completed numeric groups: year-like prefixes and comma thousands.

A four-digit prefix is strongest around 1970--2017, weaker for older or
newer years and exact centuries.  Comma groups require a preceding number,
not just a CSV field separator; decimal-heavy lists are downweighted.
Fullwidth digits follow the same rules.
Number-scale words give a smaller positive signal; the Chinese year suffix
has a negative one.  Everything else is left at zero.  A 40-character
buffer is maintained and reset at each new document.
"""
import re
import unicodedata
from atoms import FULLWIDTH_DIGITS

READS = ()


def year_signal(year):
    if 1750 <= year < 1800:
        value = 0.25
    elif 1800 <= year < 1850:
        value = 0.35
    elif 1850 <= year < 1900:
        value = 0.52
    elif 1900 <= year < 1910:
        value = 0.38
    elif 1910 <= year < 1930:
        value = 0.62
    elif 1930 <= year < 1970:
        value = 0.84
    elif 1970 <= year < 2016:
        value = 1.15
    elif 2016 <= year < 2018:
        value = 1.05
    elif 2018 <= year < 2020:
        value = 0.80
    elif 2020 <= year < 2040:
        value = 0.55
    else:
        return 0.0
    return value * (0.35 if year % 100 == 0 else 1.0)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    if token in FULLWIDTH_DIGITS or token == '，':
        token = unicodedata.normalize('NFKC', token)
    tail = (before + token)[-40:]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        match = re.search(r'[0-9]+$', tail)
        digits = match.group()
        # Inspect the number immediately before the current digit run.
        left = tail[:-len(digits)]
        group = re.search(r'(?<![0-9])([0-9]{1,3}),$', left)
        if len(digits) == 3 and group:
            value = 0.25 if group[1] in {'0', '00'} else 1.25
            numeric_tail = re.search(r'[0-9][0-9,.]*$', tail)[0]
            if numeric_tail.count('.') >= 2:
                value = 0.30
        elif len(digits) == 4:
            value = year_signal(int(digits))
    elif re.search(r'[0-9]\s*$', before):
        word = token.strip().lower()
        if word in {'million', 'billion'}:
            value = 0.38
        elif word in {'trillion', '万', '萬', '亿', '億'}:
            value = 0.25
        elif word == 'thousand':
            value = 0.18
        elif word == '年':
            value = -0.28
    return (document, tail), float(value)

programs.haiku:
"""Layer-1 MLP neuron 5954 (down_proj component): a negative response to maths notation.

What it does: the component goes negative on the symbols that build arithmetic and
algebra: plus and minus signs, powers and roots (^, ², ³, √), and the digits and
spaces inside an expression, as in "3x + 2", "x² - 4", "= -2". It is strongest for a
minus straight after "=", and for signs and powers that follow a number, variable or
closing bracket. Maths vocabulary such as "square", "triangle" or "speed" is negative
on its own. Ordinary prose and code stay near zero.

The program keeps one number of memory: a decaying count of recent operators in the
document (about the last three tokens). An "expression" is in progress when that count
is high. Then it applies a few rounded values, fit to the component's activations.
"""

READS = ()

SIGNS = {"+", "-", "–", "−"}
POWERS = {"^", "²", "³", "√"}
OPERATORS = SIGNS | POWERS | {"=", "*", "/", "×"}
CLOSERS = {")", "]", "}", ")^"}
MATH_WORDS = {
    "square", "triangle", "area", "angle", "speed", "velocity", "acceleration", "wave",
    "reaction", "quadratic", "cos", "sin", "tan", "sec", "lim", "sqrt", "shapes", "circle",
    "volume", "cubic", "perpendicular", "probability",
}
DECAY = 0.7  # about the last three tokens
BUSY = 0.23  # an operator just came before


def kind(s):
    if s in OPERATORS:
        return "operator"
    if s.isdigit():
        return "digit"
    if s in CLOSERS:
        return "closer"
    if len(s) == 1 and s.isalpha():
        return "letter"
    return "other"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if prefix.position > 0 else ""
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    recent_ops = 0.0 if new_doc or carry is None else carry
    busy = recent_ops > BUSY
    after_value = kind(before) in ("digit", "letter", "closer")  # a number, variable or ")"

    if tok in SIGNS:
        if tok == "-" and before == "=":
            value = -0.9
        elif after_value:
            value = -0.45 if tok == "+" else -0.25
        elif busy:
            value = -0.4
        else:
            value = -0.05
    elif tok in POWERS:
        value = -0.4 if (after_value or busy) else -0.2
    elif tok.isdigit():
        value = -0.35 if busy else -0.02
    elif tok == "" and busy:
        value = -0.25
    elif tok.lower() in MATH_WORDS:
        value = -0.33
    else:
        value = 0.0

    carry = DECAY * recent_ops + (1 - DECAY) * float(tok in OPERATORS)
    return carry, value

programs.sol:
"""An opening-token pulse: large before there is any distinct earlier token.

Emit a category-dependent value at document onset and during uninterrupted
repetitions of its first token; emit zero after any different token. The
strongest distinction is Cyrillic script, especially uppercase initials.
Coarse token classes approximate the remaining variation, not token IDs.
"""
import unicodedata

READS = ()
PREPOSITIONS = frozenset('to of for with from in on at by as into onto off over '
                         'under through across between about without within '
                         'against before after during until since'.split())


def onset_size(text):
    word = text.strip()
    names = ' '.join(unicodedata.name(c, '') for c in word)
    if 'CYRILLIC' in names:
        return 30.0 if word[0].isupper() else 22.5
    if text.startswith('<|'):
        return 3.7
    if not word:
        if text.strip(' ') == '':
            return min(6.5, 2.0 * len(text))
        return 2.2
    if not word.strip('#'):
        return 8.5
    if word.startswith(('//', '/*')):
        return 7.0
    if word in {'package', 'namespace'}:
        return 19.0
    if word in {'import', 'using', 'require', 'include', '#include', 'from'}:
        return 9.0
    if word.isdigit():
        return 3.6
    if 'CJK' in names or 'HIRAGANA' in names or 'KATAKANA' in names:
        return 5.4
    if word.isalpha():
        lower = word.lower()
        if lower in {'a', 'an', 'the'}:
            if not text.startswith(' '):
                return 2.7
            return 4.0 if lower == 'the' else 7.0
        if lower in PREPOSITIONS:
            return 7.0
        if lower in {'and', 'or', 'but', 'nor', 'yet', 'so', 'if', 'while',
                     'although', 'because', 'though', 'unless', 'whether'}:
            return 3.3
        return 4.8
    if all(unicodedata.category(c)[0] in 'PS' for c in word):
        return 3.0
    return 4.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, onset_size(prefix.token_strings[-1]))
    elif token != carry[1]:
        carry = (doc, carry[1], 0.0)
    return carry, carry[2]

"""Code and structured-text signposts, rather than general prose.

Recognize declaration/import words, console output, annotations, markup,
namespace paths, and opening delimiters. Simple nearby syntax distinguishes
words such as 'new' and 'this' in code from their ordinary English uses.
Document-opening idioms have separate, sometimes very large, responses.
The numbers are training-set averages, not a parser or a token-ID lookup.
"""
import re

READS = ()
DECLARATIONS = set(
    'let var def func fn function struct enum class typedef type mut'.split()
)
MODIFIERS = set(
    'public private protected static abstract virtual override readonly '
    'final async extern export'.split()
)
TYPES = set(
    'int void bool boolean float double char long short signed unsigned '
    'String string byte auto'.split()
)
CONTROL = set(
    'if else for while switch case try catch throw throws break continue '
    'goto foreach do yield'.split()
)
OUTPUT = set(
    'print println printf fprintf sprintf puts echo cout cerr WriteLine '
    'Println Printf'.split()
)
DOMAINS = set('com org net io cn java javax android'.split())
TAGS = set(
    'p div span strong br td tr table th ul li a h1 h2 h3 html head body '
    'title script style meta img link'.split()
)

# First-token responses for familiar source-file starters.
START = {
    'package': -2.52, 'using': -1.83, 'from': -1.13, 'import': -1.27,
    '#include': -1.89, '#pragma': -0.72, '#!/': -2.35, '<?': -2.28,
    '"""': -2.09, "'''": -2.09, "'use": -1.42, '//': -1.25,
    'var': -2.87, 'function': -1.78, 'export': -1.43, 'def': 1.74,
}
# Second tokens of recognizable document-opening phrases.
OPENING = {
    ('<?', 'php'): 24.88, ('Title', ':'): 24.31,
    ('What', 'is'): 10.78, ('How', 'do'): 5.51,
    ('import', '{'): 9.97, ('import', 'React'): 6.21,
    ('import', 'java'): 3.47, ('import', 'javax'): 3.47,
    ('export', 'const'): 5.91, ('using', 'System'): 3.58,
    ('#include', '<'): 4.65, ('#include', '"'): 8.67,
    ('#pragma', 'once'): 8.48, ("'use", 'strict'): 6.02,
}


def response(s, prev, age, recent):
    w, pw = s.strip(), prev.strip()
    if age == 1:
        if (prev, w) in OPENING:
            return OPENING[prev, w]
        if pw == 'package' and w.isascii() and w.isalpha():
            return 20.74 if w == 'com' else 10.30 if w == 'org' else 1.53
    if age < 5:
        if recent.startswith('---\n') and w == ':':
            if pw in {'title', 'author', 'date'}:
                return 6.01
        if recent.startswith('#!/') and w in {'/env', '/sh', '/bash'}:
            return 6.53
        if recent.startswith('<?php') and w == 'namespace':
            return 5.98
    if age < 3 and recent.startswith('/*') and w == '*':
        return 4.59
    if age == 0:
        if s in {'//\n', '//\r\n'}:
            return 4.57
        if w in START:
            return START[w]

    # Dependencies, namespace roots, and file paths.
    if pw in {'import', 'package', 'using'} and w in DOMAINS:
        if pw == 'package':
            return 6.03
        return 1.51 if w in {'java', 'javax', 'android'} else 3.25
    if pw == '#include' and (w.startswith('<') or w == '"'):
        return 2.29
    if pw == 'import' and w == '{':
        return 2.60
    if w in {'stdio', 'iostream'} and '#include' in recent:
        return 3.98
    if w == 'once' and pw == '#pragma':
        return 2.93
    if w == 'std' and pw == 'namespace':
        return 3.11
    if w == 'html' and pw.endswith('DOCTYPE'):
        return 4.60
    if w.startswith('/') and w[1:] in DOMAINS:
        return 1.28 if w[1:] in {'java', 'javax', 'android'} else 2.39
    if w in {'_modules', '-packages'}:
        return 0.83
    if w == '.com' and recent.endswith('github'):
        return 2.46
    if w in {'.com', '.org', '.net'}:
        return 0.17 if re.search(r'https?://|www\.', recent) else 0.08
    if w == '#define':
        return 2.66

    # Console-output idioms and documented parameters.
    if w == '.out' and pw == 'System':
        return 2.67
    if w == '.log':
        return 1.92
    bare = w.lstrip('(.@/')
    if bare in OUTPUT:
        return 1.34
    if w in {'System', 'Console', 'console', 'fmt', 'std'}:
        return 0.65
    if bare == 'param':
        return 1.87
    if bare in {'author', 'package'} and pw.endswith('@'):
        return 3.42
    if bare in {'return', 'returns', 'summary', 'author',
                'Override', 'Before', 'Test', 'derive'}:
        if bare != w or pw.endswith(('@', '<', '[', '#[')):
            return 1.29

    code = bool(re.search(r'[=;{}]|\b(def|const|public|return|import)\b',
                          recent))
    line_start = (not recent or s.startswith('\t') or
                  bool(re.search(r'\n[ \t]*$', recent)))
    if bare in MODIFIERS:
        return 0.97 if code or line_start else 0.0
    if bare == 'class' and pw in {'public', 'private', 'protected', 'abstract'}:
        return 2.68
    if bare in {'void', 'int'}:
        return 0.76 if bare == 'void' else 0.58
    if bare == 'main' and pw in TYPES | {'func', 'fn', 'def'}:
        return 2.01
    if bare in TYPES:
        return 0.35 if code or line_start or bare != w else 0.0
    if bare in {'const', 'namespace'}:
        return 0.84 if bare == 'const' else 1.12
    if bare in DECLARATIONS:
        return 0.61 if code or line_start else 0.08
    if bare == 'new':
        return 1.10 if pw in {'=', 'return', '(', '=>', ':', '+='} else 0.08
    if bare == 'this':
        if line_start:
            return 1.46
        return 0.71 if pw in {'=', 'return', '('} else 0.07
    if bare in {'self', 'cls'}:
        return 0.71
    if bare == 'return':
        return 0.75 if s == 'return' or s.startswith('\t') else 0.35
    if bare == 'import':
        return (2.72 if ';' in recent else 0.20) if s == 'import' else 0.85
    if bare == 'using' and s == 'using':
        return 1.37
    if bare == 'as' and re.search(r'\bimport\b[^\n]*$', recent):
        return 2.20

    # Opening punctuation and markup (newline-fused delimiters are quieter).
    if w.lstrip('</') in TAGS and (w.startswith('<') or
                                   pw.endswith(('<', '</'))):
        return 0.74
    if pw == '<h' and w in set('123456'):
        return 2.42
    if s == '\xa0' and pw in {'–', '—'}:
        return 2.38
    if s.endswith('\n'):
        return 0.0
    if w in {'{"', ',"', '["', ':"'}:
        return 0.55
    if w in {'](', '[]('}:
        return 1.40
    if w.startswith('('):
        if w in {'("', "('", '(\\"'}:
            return 0.54
        if w in {'(!', '(&', '(*', '($', '(f'}:
            return {'(!': 1.14, '(&': 1.31, '(*': 0.81,
                    '($': 0.16, '(f': 0.80}[w]
        if w == '(' and pw in CONTROL:
            return 0.82
    if w == '{':
        if pw in {'const', 'var', 'let'}:
            return 2.17
        return 0.30 if s.startswith(' ') else 0.04
    if w == '>' and re.search(
        r'(List|Set|Map|Vector|Array|Collection|Optional|HashMap|NamedList)'
        r'<[^<>]*$', recent
    ):
        return 1.15
    if w == '[]':
        return 0.53
    if w in {'#', '##', '###', '####', '//', '///', '/**', '/*', '#['}:
        return 0.46
    if w in {'@', '[@', '[@@'}:
        return 1.49 if w == '@' and pw.endswith('[') else 0.38
    if w in {'&', '<<'}:
        return 0.46 if w == '&' else 0.63
    if w in {',”', '?”', '!”'}:
        return 0.76
    if w == ':' and re.search(r'(^|\n)[A-Za-z]+$', recent):
        return 0.24
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, prev, recent = 0, '', ''
    else:
        _, age, prev, recent = carry
    s = prefix.token_strings[-1]
    value = response(s, prev, age, recent)
    return (doc, age + 1, s, (recent + s)[-100:]), value

"""Approximate function-parameter/body boundaries using familiar code syntax.

Arrow functions, Python lambda colons, and closing closure pipes receive the
strongest negative values. Definitions, function-like macros, and catch blocks
have smaller rules. Everything else is nearly zero. Fixed magnitudes average
over context: this is not a full parser or a token-specific activation table.
Keep 350 characters, normalize escaped line breaks, and reset per document.
"""
import re

READS = ()


def predict(text, token):
    before = text.rstrip()
    if re.search(r'\)=>', token):
        return -9.7
    # Arrows: recognize parameter syntax, not pointer access or implications.
    if token.strip().startswith(('=>', '->')):
        arrow = token.strip()[:2]
        header = text[-180:]
        if re.search(r'\s::\s[^\n]*$', before):
            return -2.4 if arrow == '=>' else 0.2
        single = re.search(r'(?:\(|[,=:]|\bfun)\s*[a-zA-Z_$][\w$]*$', before)
        if arrow == '->':
            if re.search(r'\b(?:def|fn|func)\s+\w+[^{};]*$', header):
                return -1.6
            java = re.search(
                r'(?:\w+\(\s*[a-zA-Z_]\w*|(?:\w+\(|[,=])\s*\([\w ,]+\))$', before)
            if token.startswith(' ->') and (java or re.search(r'\bfun\s+[\w ,]+$', before)):
                if not re.search(r'\b(?:if|while|switch)\s*\([^()]*$', before):
                    return -16.0
            if not re.search(r'\(\s*\)$', before):
                return 0.2
        if re.search(r'(?:[\'\"]|\d|\$\w+)\s*$', before):
            return -0.5
        if re.search(r'(?:\b[A-Z]\w*|::\w+|_)\s*(?:\([^()]*\))?$', before):
            return -2.8
        if before.endswith(')'):
            if re.search(r'\(\s*\)$', before):
                return -12.8
            params = re.search(
                r'\(\s*[a-zA-Z_${\[][\w$ ,:=<>?&\[\]{}.]*\s*\)$', before)
            if params and not text.endswith(('\n', '\r')):
                return -10.9
            return -2.4
        if before.endswith('>'):
            return -4.7
        if single:
            if re.search(r'\b(?:test|it)\([^;\n]*,\s*[\w$]+$', before):
                return -7.1
            return -16.0
        return -2.4

    # A Python lambda has no newline or colon between keyword and delimiter.
    m = re.search(
        r'\blambda(?:\s+([\w*]+(?:\s*=\s*\w+)?'
        r'(?:\s*,\s*[\w*]+(?:\s*=\s*\w+)?)*)\s*)?$', text[-100:])
    if m and token.startswith(':') and '\n' not in token:
        if len(token) > 1 and token[1].isalpha():
            return -11.6
        if any(p.strip() == '_' for p in (m[1] or '').split(',')):
            return -5.6
        return -20.3

    # Pipe-delimited closure parameters, following a call, move, or Ruby do.
    if '|' in token:
        if re.search(r'(?:(?:\.|::)\w+\(\|\||\bmove\s+\|\|)$', text[-40:] + token):
            return -9.9
        opener = (r'(?:(?:\.|::)\w+\(\s*|,\s*|'
                  r'\b(?:move|do|mut)\s+|\.\w+\s*\{\s*)')
        if re.search(opener + r"\|[\w ,:(&'<>*]*$", text[-120:]):
            if re.fullmatch(r'\w*\)?\|\s*', token):
                if '\n' in token:
                    return -7.0
                if '(' in text.rsplit('|', 1)[-1]:
                    return -10.5
                return -14.0

    # Closings and braces in function declarations, not in control conditions.
    if ')' in token or '{' in token or ':' in token:
        header = text[-250:]
        anon = bool(re.search(r'\bfunction\s*\*?\s*\([^()]*$', header))
        if re.search(r'\bfunction\s*\*?\s*$', header) and '()' in token:
            anon = True
        definition = bool(re.search(r'\bdef\s+\w+[?!]?\s*\([^\n]*$', header))
        js_params = bool(re.search(r'\bfunction\s*\*?\s*(?:\w+\s*)?\([^()]*$', header))
        if '{' in token:
            if '}' in token:
                return -0.002
            header += token.split('{')[0]
            if before.endswith(('=>', '->')):
                arrow = before[-2:]
                earlier = before[:-2]
                # Carry the function-boundary signal onto its opening brace.
                if predict(earlier, ' ' + arrow) > -3:
                    return -0.002
                if arrow == '->':
                    return -6.5
                return -4.1
            if anon or re.search(r'\bfunction\s*\*?\s*\([^()]*\)\s*$', header):
                if '\n' not in token and '\\' not in token:
                    return -8.7
                return -5.6
            if re.search(r'\bfunction\s+\w+\s*\([^()]*\)\s*$', header):
                if '\n' not in token and '\\' not in token:
                    return -3.1
            if re.search(r'\[[\w&,= *]*\]\s*\([\w ,*&:<>=]*\)\s*$', header):
