def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(text, token)
    text = (text + token).replace('\\n', '\n').replace('\\t', '\t')[-350:]
    return (doc, text), value

programs.haiku:
"""Lambda-body opener detector (layer 1, MLP down_proj, component 5957).

The component goes strongly negative on the token that ends a lambda's parameter list
and so announces that a body comes next:

* the arrow `=>` of an arrow function after a parenthesised list, `() =>`, `(a, b) =>`
  (about -11);
* the arrow `=>` after a bare parameter inside a call, `.filter(item =>`, `.Where(w =>`
  (about -14);
* the arrow `->` of a Java/Kotlin/C# lambda after a bare parameter in a call,
  `.forEach(x ->` (about -13), the closing `|` of a Rust closure, `.map(|x|` (about -14),
  and the colon of a Python `lambda x:` (about -13);
* the opening `{` of a function body, or the `):` of a Python `def` line (about -2.5 when
  the header has `function`/`def`/`fn`/`func`; about -3.5 after an arrow; about -1 for a
  plain `name(args) {` header).

Everything else is near zero: control-flow braces (`if`, `for`, `while`, `catch`), `->`
return-type arrows, and `=>` in match arms or PHP `as $k => $v`, which get only -1 to -2.

The program reads the newest token and the text of its own line, within its document, so
it is causal and resets at document boundaries.
"""

import re

READS = ()

# Predicted activations, each the mean of the component's activation in its class.
ARROW_AFTER_PARENS = -11.0  # `(x) =>`
ARROW_BARE_IN_CALL = -14.0  # `x =>` inside an open call
ARROW_BARE_OTHER = -2.0     # `x =>` elsewhere: match arms, PHP `as $k => $v`
ARROW_NOTHING = -1.0        # `=>` with nothing before it
LAMBDA_ARROW = -13.0        # `->` after a bare parameter in a call: `.forEach(x ->`
LAMBDA_BAR = -14.0          # closing `|` of a Rust closure in a call: `.map(|x|`
LAMBDA_COLON = -13.0        # `lambda x:` in Python
FUNCTION_PARAMS = -5.0      # `)` closing the parameters of `function(d)`, before the body
BODY_KEYWORD = -2.5         # `{` or `):` of a header with `function`, `def`, `fn`, `func`
BODY_ARROW = -3.5           # `{` after an arrow in the same line
BODY_PLAIN = -1.0           # `{` after a plain `name(args)` header

# Lines that open a control block, not a function body: `if (...) {`, `} else {`, ...
CONTROL = re.compile(r"\s*(\}\s*)?(else\s+)?(if|for|foreach|while|switch|catch|try|do|with|elif|except|finally)\b")
FUNC_WORD = re.compile(r"\b(function|def|func|fn)\b")


def _line_so_far(prefix):
    """The text of the current line before the newest token, in the current document
    (at most 400 tokens back, so a very long line stays cheap to read)."""
    doc = prefix.document_ids[-1]
    parts = []
    for i in range(len(prefix.token_strings) - 2, -1, -1):
        if prefix.document_ids[i] != doc or "\n" in prefix.token_strings[i] or len(parts) >= 400:
            break
        parts.append(prefix.token_strings[i])
    return "".join(reversed(parts)).strip()


def _arrow_value(line):
    """The activation at a `=>` that follows `line`."""
    if line.endswith(")"):
        return ARROW_AFTER_PARENS
    if re.search(r"\w\s*$", line):
        in_call = line.count("(") > line.count(")")
        return ARROW_BARE_IN_CALL if in_call else ARROW_BARE_OTHER
    return ARROW_NOTHING


def _body_value(line):
    """The activation at a `{` or `):` that ends the header `line`, 0 if it opens no function."""
    if CONTROL.match(line):
        return 0.0
    if FUNC_WORD.search(line):
        return BODY_KEYWORD
    if "=>" in line:
        return BODY_ARROW
    if line.endswith(")") and "(" in line:
        return BODY_PLAIN
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    line = _line_so_far(prefix)
    if tok.endswith("=>"):
        return carry, _arrow_value(line + tok[:-2])
    if tok == "->" and re.search(r"\.\w+\(\s*\w+\s*$", line):
        return carry, LAMBDA_ARROW
    if tok == "|" and re.search(r"\(\|\s*\w+(\s*,\s*\w+)*\s*$", line):
        return carry, LAMBDA_BAR
    if tok == ":" and re.search(r"\blambda\b[^:]*$", line):
        return carry, LAMBDA_COLON
    if tok == ")" and re.search(r"\bfunction\s*[\w$]*\s*\(\s*[\w$]+(\s*,\s*[\w$]+)*$", line):
        return carry, FUNCTION_PARAMS
    if tok in ("{", "{\\", "){", "){\\", "):", "():"):
        return carry, _body_value(line)
    return carry, 0.0

programs.sol:
"""Approximate a LA-spelling response with a small set of spelling rules.

Look for LA inside a token, L+A across tokens, or a continuation of LA.
Open LA and very short completions are strongest; longer fragments are weak.
Capitalization, script, and recent Romance function words refine the estimate.
UTF-8 fragments are assembled, and document boundaries reset all memory.
"""
import codecs
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()
ROMANCE = frozenset('de del della delle di du des le les il el los las '
                    'una une que qui che et dans pour con per en y non'.split())

@lru_cache(maxsize=32768)
def roman(text):
    text = text.replace('لا', 'la').replace('ラ', 'la')
    for letter in 'اأإ':
        text = text.replace(letter, 'a')
    for letter in 'åÅ':
        text = text.replace(letter, 'o')
    return anyascii(text)

@lru_cache(maxsize=32768)
def familiar(word):
    return word.isalpha() and max(
        zipf_frequency(word.lower(), language)
        for language in ('en', 'fr', 'es', 'it', 'de', 'pt', 'tr')
    ) >= 4


def response(raw, previous, older, romance):
    s, p, o = roman(raw), roman(previous), roman(older)
    low, pl = s.lower(), p.lower()
    # Initials such as L.A. and spaced-out L A still spell LA.
    if pl.rstrip('.').endswith('l') and low.startswith(('.a', '-a')):
        low, s, pl = low[1:], s[1:], pl.rstrip('.')
    if pl.strip() == 'l' and low.strip() == 'a':
        low, s = low.strip(), s.strip()

    if 'la' in low:
        i = low.rfind('la')
        kind, tail, lead = 'inside', low[i+2:], low[:i]
    elif low.startswith('a') and pl.endswith('l'):
        kind, tail, lead = 'split', low[1:], pl[:-1]
    elif s and s[0].isalpha() and (
        pl.endswith('la') or (pl == 'a' and o.lower().endswith('l'))
    ):
        kind, tail, lead = 'continuation', low, pl[:-2]
    elif low.strip() == 'l':
        return 0.185
    else:
        return 0.013 if s and s[0].isalpha() and pl.endswith('l') else 0.0

    n, before = len(tail.rstrip()), min(4, len(lead.strip()))
    han = bool(regex.search(r'\p{Script=Han}', raw))
    non_latin = han or bool(regex.search(
        r'\p{Script=Hiragana}|\p{Script=Katakana}', raw
    )) or bool(regex.search(
        r'\p{Script=Arabic}|\p{Script=Cyrillic}|\p{Script=Greek}',
        raw + previous
    ))
    latin_split = kind == 'split' and not non_latin

    if n == 0:
        if latin_split:
            if before == 1:
                return 3.085
            return 2.148 if romance <= .006 else 2.402
        if before:
            if before == 1:
                return .962 if kind == 'inside' and not non_latin else .044
            return .045 if before == 4 else .267
        if s.strip()[:1].isupper():
            return 2.035 if familiar(raw.strip()) else 1.021
        return 1.201 if romance <= .035 else .751

    if kind == 'split' and n == 1:
        c = tail[0]
        if c == 'h':
            return 3.042
        if c in 'ckgq':
            return 1.869 if romance <= 0 else 2.474
        return 1.691 if c in 'bmp' else .903
    if before:
        if latin_split:
            return .086 if tail[0] in 'ntd' else .433
        return .013
    if n == 1:
        return .018 if han else .656
    return .899 if kind == 'split' and n == 2 else .128


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', '', 0.0)
    _, pending, previous, older, romance = carry
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoder.setstate((pending, 0))
    raw = decoder.decode(prefix.token_bytes[-1], final=False)
    value = response(raw, previous, older, romance)
    romance = .97 * romance + .03 * (raw.strip().lower() in ROMANCE)
    return (doc, decoder.getstate()[0], raw, previous, romance), float(value)

"""Approximate a local code-expression/identifier-prefix detector.

Dollars and underscores are strongest where a variable can start, weaker in
LaTeX or inside a name.  Smaller rules cover code receivers, control-flow
parentheses, annotations, comments and prefix operators.  The carry remembers
only the previous token and 160 characters, and resets at document boundaries.
"""
import re

READS = ()
FLOW = {'if', 'for', 'while', 'switch', 'catch', 'foreach', 'unless', 'with'}
TYPES = {'int', 'float', 'double', 'char', 'long', 'short', 'bool', 'boolean',
         'void', 'String', 'string', 'const', 'var', 'let', 'auto', 'unsigned'}
ASSIGN = {'=', '+=', '-=', '*=', '/=', ':=', '=>'}
VALUE_WORDS = {'return', 'yield', 'clone', 'print', 'echo'}


def estimate(s, prev, recent):
    a, b = s.strip(), prev.strip()
    spaced = bool(s) and s[0].isspace()
    indent = bool(prev) and prev.isspace()
    code = bool(re.search(r'[;{}]|->|\$\w|\bdef\s', recent))
    expression = indent or b in ASSIGN or b in {
        'return', 'yield', 'throw', 'in', 'if', 'await', 'new', 'not',
        '(', '[', '{', ',', ':', '&&', '||', '!', '?'}
    if not a:
        return -0.07 if '\xa0' in s else 0.01

    if '$' in a:
        math = bool(re.search(
            r'\\(?:frac|left|right|begin|end|math\w*|sum|prod|int|partial|'
            r'alpha|beta|gamma|delta|sigma|phi|epsilon|lambda|mu|theta|pi)\b',
            recent))
