            return -0.17
        if '${' in a:
            return 0.53
        if a.startswith(('}', ']')) and a.endswith('$'):
            return 0.0
        if a.endswith('$'):
            if not recent:
                return -1.61
            if b in {'my', '(my'}:
                return 6.85
            if b in {'=>', 'as'} and (code or b == '=>'):
                return 5.51
            if b in ASSIGN or '=' in a:
                return 4.73
            if b in VALUE_WORDS:
                return 4.76
            if '(' in a or b in {'(', '!', '&&', '||'}:
                return 4.58 if sigils else 2.75
            if b in TYPES:
                return 3.49
            if indent:
                if prev.endswith((' ', '\t')) and len(prev) >= 2:
                    return 0.49 if math else 4.44
                return 4.44 if sigils else 2.33
            if b in {'.', '<', '>', '+', '-', ',', '==', '<=', '>=',
                     'while', 'unless'} or b.endswith('),'):
                return 5.25 if sigils else 0.90
            if '\\$' in a or b.endswith('\\'):
                return 4.52 if sigils else 1.38
            if a == '$' and not spaced:
                return 0.19
            return 2.01 if sigils else 0.53
        if a.startswith(('$', '($')):
            return 0.30

    if a.endswith('_') and not any(c.isalnum() for c in a):
        if a == '__':
            return 1.49 if spaced else 0.40
        if a == '_':
            if b == '_':
                return 0.85
            if re.search(r'\\[A-Za-z]+$', recent):
                return -0.15
            if spaced or indent:
                return 2.5 if expression else 1.8
            return 0.06
        return 1.54 if a.startswith(('.', '(', '[', '<', '&')) else 0.54

    if set(a) == {'`'}:
        return {1: 0.17 if spaced else 0.05, 2: 0.33}.get(len(a), 0.10)
    if a.startswith(('//', '/*')):
        return 0.27
    if a.endswith('@') and len(a) <= 3:
        return 1.86 if a.startswith(',') else (1.34 if spaced else 0.40)
    if a == '#[':
        return 1.20
    if a.endswith('#'):
        return 0.52 if spaced else 0.30
    if a.startswith('('):
        rest = a[1:]
        if not rest and b in FLOW:
            return 0.78
        if rest in TYPES:
            return -0.27 if rest == 'double' else 0.36
        if rest in {'this', 'self'}:
            return 0.43
        if rest.startswith('!'):
            return 0.80
    if a in {'this', 'self'}:
        if indent or '\t' in s:
            return 0.98
        if b in ASSIGN or b in {'return', 'yield', 'await', 'new'}:
            return 0.73
        if code and (expression or b.endswith(')')):
            return 0.73
        return 0.67 if not spaced else 0.02
    if a in {'const', 'var', 'let'}:
        return 0.34
    if a == 'double':
        return -0.21
    if a == '::':
        return 1.95 if b == 'std' else 0.0
    if a == '->':
        return 1.37 if b == 'this' else 0.0
    if a == '0' and b == '.':
        return -0.26
    if spaced and a in {'-', '--', '+', '++', '*', '/', '.', ':', '&', '%', '\\'}:
        if a in {'--', '++'}:
            return 0.61
        if a == '.' and indent:
            return 0.73
        if a == '&' and (b in TYPES or '(' in b or b.endswith(',')):
            return 0.88
        if a in {'-', '/'} and b in {'python', 'python3', 'cat', 'sed', 'grep',
                                     'ls', 'git', 'npm', 'pip'}:
            return 1.19
        return 0.25 if expression else 0.10
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, recent = '', ''
    else:
        _, prev, recent = carry
    token = prefix.token_strings[-1]
    value = estimate(token, prev, recent)
    return (doc, token, (recent + token)[-160:]), value

programs.haiku:
"""Fires on the token that opens a name in source code, so the model is about to write a
variable or identifier: the sigil of a PHP/Perl variable ($x, @x), the leading underscore of
an identifier (_color), a dunder (__init__), 'self', a member dot, and the '(' of an if/for/
foreach test. Weaker on comment and scope markers (#, //, ::, ->). Strongest where the recent
text looks like code (semicolons, braces, arrows), weak in LaTeX maths."""
READS = ()

BASE = {"$": 3.9, "@": 1.6, "_": 4.2, "__": 3.2, " self": 1.4, " .": 1.2, "if(": 0.9, "marker": 0.5}
MARKERS = ("#", " #", "::", "//", " //", "->")
CODE_CHARS = (";", "{", "}", "->", "=>")
TEST_WORDS = (" if", " for", " foreach", " while", "\tif", "\tfor")

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if raw.lstrip(" ([{&\\").startswith("$"):
        key = "$"
    elif raw.lstrip(" ([{&\\").startswith("@"):
        key = "@"
    elif raw.lstrip(" ([{&") == "_" and raw[:1] in (" ", "(", "&"):
        key = "_"
    elif raw.lstrip(" ([{&") == "__" and raw[:1] in (" ", "("):
        key = "__"
    elif raw in (" self", " ."):
        key = raw
    elif raw in (" (", "(") and prev in TEST_WORDS:
        key = "if("
    elif raw in MARKERS:
        key = "marker"
    else:
        return None, 0.0
    recent = "".join(prefix.token_strings[-60:-1])
    if "\\" in recent:
        return None, 0.3 * BASE[key]
    marks = sum(recent.count(c) for c in CODE_CHARS)
    level = min(1.0, marks / 4.0)
    return None, BASE[key] * (0.2 + 0.8 * level)

