"""Approximate the component with sparse lexical and formatting triggers.

A valid stem followed by an earthly branch (the Chinese calendar's two-character
names) gives a strong positive response.  Turtle glyphs and selected CJK word
endings also respond, with stronger values for compounds such as abalone and
oil.  Separate rules cover Thai 'home', middle dots, and a few document-opening
layout markers.  Everything else is zero; this does not model the small,
varied background activations. Character rules act only when a token completes
one character. UTF-8 fragments and document resets are handled.
"""
from codecs import utf_8_decode

READS = ()
HEAVENLY_STEMS = "甲乙丙丁戊己庚辛壬癸"
EARTHLY_BRANCHES = "子丑寅卯辰巳午未申酉戌亥"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending = '', b''
    else:
        _, previous, pending = carry
    raw = pending + prefix.token_bytes[-1]
    # Incomplete final characters must wait for the next token.
    text, used = utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    tail = (previous + text)[-12:]
    value = 0.0
    if text == '加油':
        value = 4.0
    elif text == '··':
        value = 1.7
    elif text in ('้าน', 'บ้าน') and tail.endswith('บ้าน'):
        value = 0.8
    elif len(text) == 1:
        char = text[-1]
        if (len(tail) >= 2 and char in EARTHLY_BRANCHES
                and tail[-2] in HEAVENLY_STEMS
                and HEAVENLY_STEMS.index(tail[-2]) % 2
                    == EARTHLY_BRANCHES.index(char) % 2):
            value = 7.0
        elif char in '龟龜亀':
            value = 2.4 if char == '龟' else 5.8
        elif tail.endswith(('鲍鱼', '鮑魚')):
            value = 4.4
        elif char in '鱼魚':
            value = 0.25
        elif char in '寅卯酉戌':
            value = 1.5
        elif char in '辰巳申':
            value = 0.7
        elif tail.endswith('貝葉'):
            value = 3.3
        elif char == '油':
            value = 0.45
            if tail.endswith(('加油', '抽油', '柏油')):
                value = 3.0
        elif char == '谷':
            value = 1.4
        elif char == '子':
            value = 0.05
            if tail.endswith('双子'):
                value = 2.2
            elif tail.endswith(('奶子', '辛子', '麻子', '千子', 'お子')):
                value = 1.1
        elif char == '癒':
            value = 2.0
        elif char == '隣':
            value = 1.8
        elif tail.endswith('跳蛋'):
            value = 0.75
        elif tail.endswith('久保'):
            value = 0.8
        elif tail.endswith('久未'):
            value = 0.7
    if text == '\r' and not previous.strip('\r'):
        value = -5.66
    elif text == '//\n' and not previous:
        value = -3.44
    elif text == r'\t' and not previous.replace(r'\t', ''):
        value = 2.07
    elif not previous and prefix.token_bytes[-1].lstrip().startswith(b'\\\\"'):
        value = 1.2
    return (doc, tail, pending), value

programs.haiku:
"""Two things this component reacts to, and nothing else.

1. The first token of a document (position 0 after a document break, including
   the start of a row). Its value depends only on that token: word-like tokens
   (English letters without a leading space, or Chinese characters) push it
   negative; digits, symbols and everything else push it slightly positive.
2. Runs of middle dots "·" (leader dots), which hold a strong constant value.
Everywhere else the component is essentially silent (about 0).
"""
READS = ()

LATIN = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
DOT = "·"


def _is_cjk(c):
    return "一" <= c <= "鿿"


def _word_like(tok):
    s = tok.strip()
    return bool(s) and (all(c in LATIN for c in s) or all(_is_cjk(c) for c in s))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        if _word_like(tok):
            value = -0.1 if tok.startswith(" ") else -0.3
        else:
            value = 0.05
    elif tok and set(tok) == {DOT}:
        value = 1.7
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a brit/ritt spelling-fragment response, not a general topic detector.
Romanize the current word and favor short rit/rid/itt fragments. Common whole
words are mostly quiet. Britain (especially after 'great'), British, brittle,
and the Chinese character meaning brittle get separate strengths. Some imit,
herit and iter fragments, and document-initial 'it', have negative responses.
The carry holds only the current word, reset at each document boundary.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
