    "call": {"call", "invoke"},
    "run": {"run", "execute"},
    "import": {"import"},
    "override": {"override"},
    "implement": {"implement"},
    "action": {"apply", "access", "refer", "see", "install", "configure",
               "specify", "edit", "modify", "test", "check", "define"},
