    if w == "of" and p in {
            "implementation", "implementations", "invocation", "instance",
            "instances", "output", "outputs"}:
        value -= 0.16
    if w == "by" and p in {
            "called", "used", "invoked", "implemented", "triggered",
            "generated", "computed", "calculated", "created", "obtained"}:
