"""Layer 1, MLP down_proj, component 5964.

Negative when the text is about to name a piece of code that is being used, called,
run, invoked or overridden. It is strongest on the verb and the word after it
("use THE", "call TO", "override `"), on Javadoc links ("{@link"), and on an opening
backtick around a code name in prose ("the `", "of `", "running `"). Elsewhere it is
near zero. The values are in activation units: about -1 for a typical hit, about -2 to
-3 for the strongest. Everything not listed predicts 0.
"""

READS = ()

# Verbs for using, calling, running, invoking or overriding code.
USE_VERBS = {
    "use", "uses", "used", "using", "utilize", "utilise", "utilizing",
    "call", "calls", "called", "calling", "invoke", "invokes", "invoked",
    "invoking", "invocation", "run", "running", "runs", "override",
    "overrides", "overridden", "overriding", "mock", "import", "via", "hit",
}
STRONG_VERBS = {"override", "overrides", "overridden", "overriding", "invoke", "invokes", "invoked", "invoking"}
# Words that introduce the object of a verb ("use THE thing", "call TO ...").
OBJECT_WORDS = {
    "the", "a", "an", "this", "that", "your", "my", "its", "their", "our", "to", "with", "by", "via", "of",
}
# Words after which an opening backtick starts a code name in prose.
PREPS = OBJECT_WORDS | {"in", "for", "from", "on", "running"}


def _norm(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = [_norm(s) for s in prefix.token_strings[-3:]]
    word = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if word in STRONG_VERBS:
        return None, -2.0
    if word in USE_VERBS:
        return None, -0.5
    if word == "link" and prev == "{@":
        return None, -2.5
    if word == "`":
        if prev in PREPS:
            return None, -1.3
        if prev in USE_VERBS:
            return None, -1.0
        return None, -0.2
    if word in OBJECT_WORDS and prev in USE_VERBS:
        return None, -0.8
    if word == "with" and prev == "completed":
        return None, -1.5
    return None, 0.0

