BE = {'be', 'been', 'being', 'is', 'are', 'was', 'were', 'get', 'got'}
OUTCOME = re.compile(
    r'(?:maintain|attain)(?:s|ed|ing)?|(?:achiev|manag)(?:e|es|ed|ing)'
)
