    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    p = '' if first else carry[1]
    previous_was_first = carry is not None and carry[2]
    left_word = '' if first else carry[3]
    tail = re.search(r'[A-Za-z]+$', left_word + s)
    word = tail.group().lower()[-40:] if tail else ''
