            value -= 1.65 if q.endswith('ed') else 2.0
        elif re.fullmatch(r'attain(?:s|ed|ing)?', q):
            value -= 2.1
        elif re.fullmatch(r'achiev(?:e|es|ed|ing)', q):
            value -= 1.0 if q.endswith('ed') else 2.1
        elif re.fullmatch(r'manag(?:e|es|ed|ing)', q):
            value -= 1.65 if q.endswith('ed') else 1.5
        elif re.fullmatch(r'gain(?:s|ed|ing)?', q):
            value -= 1.6 if q.endswith('ed') else 0.9
        elif re.fullmatch(r'arrang(?:e|es|ed|ing)', q):
            value -= 0.95
        elif re.fullmatch(r'ag(?:ed|ing)', q):
            value -= 1.05
        elif re.fullmatch(r'alleg(?:e|es|ed|ing)', q):
            value -= 0.4
        elif re.fullmatch(r'augment(?:s|ed|ing)?', q):
            value -= 1.0
        elif q in ('aunt', 'aunts'):
            value += 1.8
        elif q == 'august':
            value -= 0.5
        elif q == 'aug':
            value -= 1.4
        elif s.startswith(' ') and q == 'ange':
            value -= 0.9
