            elif q.startswith('uch'):
                value -= 1.3 if a == 'a' else 2.6
            elif q == 'ute':
                value += 2.4
            elif q in ('uld', 'ult'):
                value += 3.5
            elif q == 'ut':
                value += 0.7
            elif q in ('uss', 'uf'):
                value -= 1.5
            elif q.startswith('ust'):
                value -= 0.7
        if q == 'ault':
            value += 2.6
        elif q == 'aut':
            value += 2.8 if a.endswith('n') else 0.6
        elif q == 'ould' and a.endswith('rn'):
            value += 4.0
        elif q == 'aug':
