"""Word detector for layers.1.mlp.down_proj unit 5965 (layer 1).

The unit is close to silent except on a short list of words. It is most negative on
verbs of achieving, managing and keeping up: "achieve", "attain", "maintain",
"manage" (every inflection, e.g. "to achieve", "managed to", "maintaining"), and
weaker on "gain", "arrange", "amass", "age", "choose". It is weaker when such a verb
follows a form of "be" (a passive). It is also negative on the "aug" spelling
(August, Aug, augment, augmented) and on "assistant". It is positive on a few
name-like pieces ("aut", "ault", "gal", "Gall", "unt", "aunt") and on the middle dot
"··". Everything else predicts 0.

Words are rebuilt from tokens: a token with no leading space that continues a word
(e.g. "Maint" + "ained") extends the word, so a split verb still counts at the piece
that completes it.
"""

import wordnet

READS = ()

# activation for each verb lemma, in the same units as the component
VERB_VALUE = {
    "achieve": -1.9, "attain": -1.9, "maintain": -1.9, "manage": -1.9,
    "gain": -1.2, "arrange": -1.2, "amass": -1.0, "age": -0.6, "choose": -0.4,
}
BE_FORMS = {"be", "is", "are", "was", "were", "been", "being"}
PIECES = {"aut": 0.8, "ault": 1.2, "gal": 1.0, "Gall": 1.2, "aunt": 2.5, "Aunt": 1.5, "unt": 0.5}


def verb_value(word):
    """The value for a word whose base form (wordnet lemma) is in VERB_VALUE, else 0."""
    if not word.isalpha():
        return 0.0
    for lemma in wordnet.base_forms(word):
        if lemma in VERB_VALUE:
            return VERB_VALUE[lemma]
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = prefix.position == 0 or (
        len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if carry is None or new_document:
        word, previous = "", ""
    else:
        word, previous = carry
    if not token[:1].isalpha():
        # a space, punctuation or symbol ends the word; it becomes the previous word
        previous = word.lower() if word else previous
        word = ""
    if token[:1].isalpha() and word:
        word = word + token
    elif token[:1].isalpha() or token[:1] == " ":
        word = token.strip()
    new_carry = (word, previous)

    value = verb_value(word.lower())
    if value:
        return new_carry, value * (0.4 if previous.lower() in BE_FORMS else 1.0)
    if token.strip().lower().startswith("aug"):
        return new_carry, -1.0
    if token.strip() == "assistant":
        return new_carry, -0.3
    if token in PIECES:
        return new_carry, PIECES[token]
    if token == "··":
        return new_carry, 0.73
    return new_carry, 0.0

