import unicodedata
from functools import lru_cache

import inflect
import regex
from wordfreq import zipf_frequency

READS = ()
NUMBER_WORDS = frozenset(
    inflect.engine().number_to_words(n) for n in range(13)
)


@lru_cache(maxsize=32768)
def token_value(text, raw, opening):
    word = text.strip()
