        if word.lower() in NUMBER_WORDS:
            return -0.85 if text.istitle() else -0.35
        value = 0.06 + 0.08 * text.startswith(' ')
        if word.isascii() and word.isalpha():
            if zipf_frequency(word.lower(), 'en') >= 7:
