    return -0.002 if text.startswith(' ') else 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
        position += 1
    value = token_value(text, prefix.token_bytes[-1], position == 0)
    if position:
        # The small initial negative bias fades within a few tokens.
        value -= 0.02 if position <= 2 else 0.018 / (position - 1) ** 2
        if position == 1 and previous == '1' and text == '2':
            value = -2.271
        elif position == 1 and previous == 'Title' and text == ':':
            value = 1.128
