    if not token[:1].isspace():
        value = 4.0 if contiguous or token.startswith('-') else 2.2
    if stem in {'upside', 'tear'}:
        return 0.3
    if contiguous and stem in {'cool', 'slow', 'touch'}:
        return 1.8
    if contiguous and stem in {'count', 'knock', 'run', 'take'}:
        value = 6.0
    if low == 'down' and stem in {'count', 'knock'}:
        value = 8.0
    if stem == 'mark':
        value = 5.5 if low == 'down' else 4.6
        if low == 'down' and before.endswith('.mark'):
            value = 8.2
    if low in {'own', 'owns'} and history.endswith('d'):
        value = 10.5

    recent = [bases(w) for w in words[-5:]]
    immediate = bases(stem)
    breaking = any('break' in b for b in recent) or stem.endswith('break')
