def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = '', 0.0
    else:
        _, history, previous = carry
    token = prefix.token_strings[-1]
    low = token.lower()
    text = history + low
    hits = [m for m in re.finditer('down', text)
            if m.end() > len(history)]
