    elif low.strip() in {'dn', 'dw'}:
        value = 1.3
    elif low.strip() == 'own':
        value = -0.35
    elif low.strip() in {'under', 'lower', 'below', 'minimum'}:
        value = 0.25
    elif previous:
        if low == ' the':
