        # Korean ability and prospective/nominalizing constructions.
        if s == '수':
            return -16.8 if token.startswith(' ') else -10.0
        if s in ('것', '것이'):
            return -14.8
        if s == '거' and token.startswith(' '):
            return -10.0
        if s.startswith('것'):
            return -7.0
        if s in ('지', '지도'):
            return -6.0
