            return -1.0
        if p == 'ul':
            return -3.0
    if p == 'ud':
        return 0.0
    if not separate:
        return 0.0
    if token == ' ':
        return -6.9 if p == 'el' else (-2.6 if p == 'al' else -4.0)
    if s.startswith(("'", '’')):
        return -1.1
    if token.startswith(' ') and s.isalpha():
        if s[0].isupper():
            scale = 1.0 if p in ('al', 'el') else 0.3
            return scale * (-4.5 if len(s) <= 3 else -1.4)
        if len(s) <= 3:
            return -1.6 if p == 'al' else (-0.5 if p == 'el' else -0.2)
        return -0.3 if p == 'al' else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
