import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=50000)
def spelling(s):
    t = s.strip()
    low = anyascii(t).lower()
    latin_l = bool(re.search('[a-z]', t.lower())) and 'l' in low
    consonants = sum(c in 'bcdfghjkmnpqrstvwxyz' for c in low)
    arabic = bool(regex.search(r'\p{Script=Arabic}', t))
    article = t.startswith(('ال', 'وال', 'بال', 'فال', 'لل'))
    return t, low, latin_l, consonants, arabic, article


def letter_value(s, previous, turkish, previous_lam):
    t, low, latin_l, consonants, arabic, article = spelling(s)
    leading = s[:1].isspace()
    n = len(t)
    value = 0.0
    if 'ل' in t:
        if leading:
            if article:
                value += .05
            if t in ('ل', 'لل'):
                value += .61
            if not article and t.endswith('ل') and n > 1:
                value += 1.28
            if t in ('لا', 'لي', 'له'):
                value += 1.64
        else:
            if t == 'ل':
                value += 3.33
                if previous.endswith(('ی', 'ي', 'ى', 'و')):
                    value -= 2.68
            elif t.endswith('ل'):
                value += 3.09
            elif t.endswith(('لا', 'لي', 'له', 'لية')):
                value += 3.82
            else:
                value += 1.01
            if n > 4:
                value -= .85
            if t.endswith('قل'):  # lam following the uvular stop qaf
                value += 2.67
            if t.endswith('ول'):  # lam following waw
                value -= 1.46
            if t.startswith('ال') and not previous[-1:].isalpha():
                value -= .95
    elif arabic and not leading and n <= 2:
        value += .28 * max(0.0, previous_lam)
    if latin_l and t.isalpha() and n <= 5:
        if not leading:
            value += .02
        if turkish > .75:
            if consonants == 0 and not leading:
                value += 1.87
            elif consonants == 1:
                value += .61 if low.startswith('l') else 1.07
        if 'ı' in t and n <= 4:
            value += .22
    if 'л' in t.lower() and n <= 3 and not leading:
        value += .07
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, turkish, position, previous_lam = '', '', 0.0, 0, 0.0
    else:
        _, previous, word, turkish, position, previous_lam = carry
    s = prefix.token_strings[-1]
    if s[:1].isspace() or not previous[-1:].isalpha():
        if word.isalpha() and len(word) > 1:
            contrast = zipf_frequency(word, 'tr') - zipf_frequency(word, 'en')
            turkish = .9 * turkish + .1 * max(-3, min(3, contrast))
        word = ''
    tail = re.search(r'[^\W\d_]+$', s)
    word = ((word if tail.start() == 0 else '') + tail.group()) if tail else ''
    value = letter_value(s, previous, turkish, previous_lam)
    lam = value if 'ل' in s and not s[:1].isspace() else 0.0
    if position == 0:
        value += .12
    if position == 1 and previous == 'Title' and s == ':':
        value = 19.33
    return (doc, s, word, turkish, position + 1, lam), float(value)

