import regex
from wordfreq import zipf_frequency

READS = ()
LINKS = set('of to for by from about between after before'.split())
PLACE_AND_ROLE_LINKS = set('in on at with as over under into through'.split())
SUBORDINATORS = set('if when while because since although unless than'.split())
SOURCE_HEADERS = {'package': 10.75, 'import': 6.1, 'using': -0.2}


def opening_value(token):
    word = token.strip()
    lower = word.lower()
    space = token.startswith(' ')
    capital = word[:1].isupper()
    if token == '<|im_start|>':
        return 6.84
    if token.startswith('<|'):
        return 4.2
    if token == '\r':
        return 15.9
    if not word:
        return 0.0
    if word.isdecimal():
        return -0.48
    if '\ufffd' in word:
        return 4.5
    if not any(c.isalpha() for c in word):
        if word in {'.', ',', '，', '。', ':'}:
            return 3.0 if '\n' in token else -0.4
        if token in {'//\n', '#\n'}:
            return 24.0
        if word.startswith('#'):
            return 5.8
        if word.startswith('//'):
            return 5.0
        if word.startswith('('):
            return 2.6
        if word.startswith('['):
            return 6.5
        if word.startswith(('"', "'")):
            return 4.0
        return 2.0
    if token in SOURCE_HEADERS:
        return SOURCE_HEADERS[token]
    if word.startswith('#'):
        return 5.7
    if lower == 'the':
        return 7.2 + 2.0 * capital + 2.5 * (space and capital)
    if lower == 'a':
        return 3.7 if space else 0.3
    if lower == 'an':
        return 11.0 + 4.0 * capital
    if lower in LINKS:
        return 0.3 + 0.8 * capital
    if lower in PLACE_AND_ROLE_LINKS:
        return 2.0 if space else 4.7
    if lower in SUBORDINATORS:
        return 0.9
    if regex.search(r'\p{Script=Han}', word):
        return 2.3
    if word.isupper():
        if len(word) == 1:
            if word == 'I':
                return 6.0 if space else 9.1
            if word in 'AEIOU':
                return 1.5
            return 4.2 if space else 8.0
        return 3.5
    if len(word) > 3 and word.isascii() and word.isalpha():
        rare = zipf_frequency(word, 'en') < 3.0
        if capital:
            return (3.0 if space else 3.9) + 3.0 * rare
        if space:
            return 4.6 if rare else 2.8
        return 3.7
    if capital:
        return (5.0 if space else 6.4) if len(word) <= 3 else 3.5
    return 2.9 if space else 4.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, value), value
    _, opening_token, value = carry
    if token != opening_token:
        opening_token, value = None, 0.0
    return (doc, opening_token, value), value

