            'what': 3.0, 'whatever': 2.4, 'anything': 1.4,
            'everything': 1.4,
            'all': 2.7, 'both': 3.2, 'otherwise': 4.7,
            'the': 0.7, 'just': 4.0, 'better': 1.1,
