        elif roots & {'accomplish', 'achieve'}:
            value = {'this': 4.5, 'that': 3.0, 'it': 2.0}.get(word, value)
        elif roots & {'show', 'illustrate', 'demonstrate', 'explain'}:
            value = {'this': 2.5, 'it': 0.6}.get(word, value)
        elif roots & {'see', 'know', 'think'}:
