SAY_FORMS = {"say", "says", "said", "saying"}
# how strongly each pro-form fires right after a do-form
PRO_FORM = {"so": 8.0, "this": 5.0, "that": 4.4, "same": 5.0, "it": 2.7,
            "just": 4.6, "what": 3.1, "anything": 1.2, "|": 6.7}


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings]
    cur = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""
    if prev in DO_FORMS:
        return None, PRO_FORM.get(cur, 0.0)
    if prev in ("the", "just") and prev2 in DO_FORMS and cur in ("same", "that"):
        return None, 4.0
    if prev in SAY_FORMS and cur == "so":
        return None, 6.0
    if prev in SAY_FORMS and cur == "this":
        return None, 3.0
    if cur == "with" and prev in DO_FORMS:
        return None, -4.0
    if cur == "do" and prev == "to":
        return None, -8.0 if prev2 == "nothing" else -2.0
    if cur == "1" and prev == "{" and prev2 == "frac":
        return None, -2.4
    return None, 0.0

programs.sol:
"""Approximate the large numeric and formatting responses seen in training.

Positive: continuations of 3 into 30/31, even line indentation, and TeX row
breaks/labels. Doubled backslashes outside TeX are usually negative. Bare
carriage-return prefixes are strongly positive. Separate rules recognize the
stems short/kurz/kort. Unrecognized tokens predict zero. State holds at most
256 recent characters and resets at document boundaries.
"""
import calendar
import re
import unicodedata

READS = ()
MONTHS = tuple(name.lower() for name in
               (*calendar.month_name[1:], *calendar.month_abbr[1:]))
TEX = re.compile(
    r"(?<!\\)\\(?:begin|end|frac|left|right|[a-z]*matrix|math[a-z]*|"
    r"alpha|beta|gamma|delta|sigma|theta|phi|lambda|mu|vec|sum|quad|"
    r"hfill|cdot|nonumber|overline|partial|label|text|times|int|hat)\b")


def is_math(text):
    return bool(TEX.search(text))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0

    digit = unicodedata.normalize('NFKC', token)
    if digit in ('0', '1'):
        number_history = unicodedata.normalize('NFKC', history[-64:])
        match = re.search(r'(\d+)$', number_history)
        if match and match[1].endswith('3'):
            start = len(match[1]) == 1
            value = (1.2 if start else 0.52) if digit == '0' else (
                0.72 if start else 0.24)
            if start:
                before = number_history[:-1]
                if digit == '0' and before.endswith(':'):
                    value = 1.5
                if before.endswith('月') or any(
                        before.lower().rstrip().endswith(m) for m in MONTHS):
                    value += 0.7
        elif digit == '0' and re.search(r'3[.,]$', number_history):
            value = 0.55

    # Even indentation is stronger after code delimiters than after blank lines.
    if token and not token.strip(' \t'):
        width = token.count(' ')
        if width and width % 2 == 0:
            if re.search(r'\n\t*$', history):
                value = 0.55 if width <= 4 else 0.25
                line = history.rstrip('\n\t')
                if line.endswith('{'):
                    value += 0.25 if width == 2 else 0.5
                elif width >= 4 and line.endswith((';', ')', ':')):
                    value += 0.3
            elif '\t' in token:
                value = 0.45
    if token == '\r':
        value = 6.68 if not history.strip('\r') else 0.15

    if '\\\\' in token:
        if token.rstrip().endswith('"'):
            value = 0.8
        elif is_math(history):
            value = 2.8
        else:
            serialized = '\\n' in history or '\\"' in history
            value = 2.5 if token.startswith(' ') and not serialized else -1.5
            if not history:
                value = 0.8
            if history.endswith('\\"'):
                value = -2.3 if history.endswith('(\\"') else -1.9
            if token.count('\\') > 2:
                value = 0.2
    if token in ('\n', ' \n', ' \\') and history.endswith('\\\\'):
        value = 1.15
    if token == '\\"' and history.endswith('\\\\'):
        value = 1.1

    # TeX commands that delimit lines, rows, and equation labels.
    command = re.search(r'(?<!\\)\\([A-Za-z]*)$', history)
    if command:
        whole = command[1] + token
        if whole in ('cr', 'newline', 'tabularnewline'):
            value = 6.0 if whole == 'cr' else 2.8
        elif whole in ('h', 'hline'):
            value = 1.8 if whole == 'h' else 2.7
        elif whole == 'label':
            value = 1.4
        elif whole == 'non':
            value = 1.9

    lower = token.lower().lstrip()
    if lower == 'thirty':
        value = 0.65
    elif lower.startswith('short'):
        value = 1.2 if lower.startswith('shortly') else 0.3
    elif lower.startswith(('kurz', 'kort')):
        value = 2.1 if lower.startswith('kurz') else 1.5
    else:
        word = re.search(r'([A-Za-zäöüÄÖÜ]+)$', history)
        if word:
            old = word[1].lower()
            if old in ('sh', 'kur', 'kür', 'k') and (old + token.lower()).startswith(
                    ('short', 'kurz', 'kürz', 'kort')):
                value = 2.4

    return (doc, (history + token)[-256:]), value

"""Approximate a document-onset signal, including identical opening repeats.

Emit a pulse at the first visible token of each document or row. Keep it on
while this token repeats, then turn it off. Unspaced letters, especially
capitals, usually get larger pulses than punctuation. Estimate the amplitude
from character classes rather than memorizing individual words.
"""
import regex
import unicodedata

READS = ()


def onset(text):
    word = text.strip()
    spaced = text.startswith(' ')
    if word.startswith('<|'):
        return 5.7
    if not word:
        if '\t' in text:
            return 7.5 if len(text) == 1 else 5.3
        if '\n' in text:
            return 5.1 if text == '\n' else 4.0
        return 3.0 if text == ' ' else 4.4
    if word.isdecimal():
        return 8.3 if word == '0' else 4.4
    if regex.search(r'\p{Han}|\p{Hiragana}|\p{Katakana}', word):
        return 4.5
    if word[0].isupper():
        return 5.8 if spaced else 7.3
    if word[0].islower():
        return 5.6 if spaced else 6.6
    if not any(ch.isalnum() for ch in word):
        if '\n' in text:
            return 4.8 if text.count('\n') == 1 else 3.5
        category = unicodedata.category(word[0])
        if category == 'Ps':  # Opening brackets.
            return 4.9 if spaced else 5.6
        if category in ('Pe', 'Pf'):  # Closing brackets and quotation marks.
            return 2.0 if spaced else 1.5
        if word in set(',.;:!?，。；：？！、'):
            return 2.4 if spaced else 1.8
        return 3.7 if spaced else 3.0
    return 5.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = onset(prefix.token_strings[-1])
        carry = (doc, token, value)
    elif token != carry[1]:
        carry = (doc, None, 0.0)
    return carry, carry[2]

programs.haiku:
"""Candidate C: doc-start value by kind of first token, plus filler dots."""
READS = ()

# Mean activation at a document's first token, by what the token looks like.
KIND_VALUE = {
    "capitalised word": 7.3,
    "lowercase word": 6.7,
    "spaced word": 5.6,
    "digit": 5.2,
    "non-ASCII letters": 5.0,
    "punctuation or blank": 3.9,
    "other symbol": 2.8,
}

def kind(tok):
    s = tok.lstrip(" ")
    if s == "":
        return "punctuation or blank"
    c = s[0]
    if c.isascii() and c.isalpha():
        if tok[0] != " " and c.isupper():
            return "capitalised word"
        if tok[0] != " ":
            return "lowercase word"
        return "spaced word"
    if c.isascii() and c.isdigit():
        return "digit"
    if c.isascii():
        return "punctuation or blank"
    if c.isalpha():
        return "non-ASCII letters"
    return "other symbol"

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == "··":          # a run of filler dots: always active
        return None, 7.5
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        return None, 0.0     # only a document's first token fires
    return None, KIND_VALUE[kind(tok)]

programs.sol:
r"""Boundary and formatting response in an early MLP.

A bare carriage return, an empty // comment line, or a markup declaration
at a document's start gives a large negative response. Repeated initial
symbols retain their boundary response. Ordinary text has a small response:
negative for uncontextualized fragments, less negative for grammatical
sentence openers. The small punctuation offsets distinguish opening from
closing delimiters. A single space after a literal \n escape and an
include directive's opening angle bracket are negative interior cases.
Most other positions are predicted near zero.
"""
READS = ()

AUXILIARIES = set('''be am is are was were been being have has had do does
    did can could may might must shall should will would'''.split())
FUNCTION_WORDS = set('''the an in on at to for from by with after before
    under over between through without about and or but as if because when
    while although therefore however moreover'''.split())
PERSONAL_PRONOUNS = set('i me you he him she her it we us they them'.split())
DEMONSTRATIVES = set('this that these those'.split())


def boundary_value(token):
    word = token.strip()
    lower = word.lower()
    if token == '\r':
        return -4.65
    if token == '//\n':
        return -7.34
    if token == '<!':
        return -9.07
    if token == '<|im_start|>':
        return 0.305
    if lower == 'user':
        return -1.25
    if lower == 'assistant':
        return -0.65
    if token == 'Title':
        return -0.527
    if token == ' .':
        return 1.40
    if token == '··':
        return 0.675
    if token in ('(', '[', '{'):
        return -0.28
    if token in (')', ']', '}'):
        return 0.22
    if word in ('.', ':') and token.endswith('\n'):
        return -0.75 if token.count('\n') == 1 else -0.20
    if word == ',':
        return -0.28
    if word == ':':
        return -0.14
    if word == '//':
        return 0.44
    if word == '/*':
        return -0.32
    if word == '#':
        return 0.07
    if not word:
        if '\n' in token:
            return 0.16 if token.strip('\n') == '' else -0.20
        if '\t' in token:
            return -0.24
        return -min(0.07 * len(token), 0.25)
    if word.isdecimal():
        return -0.14
    if lower in AUXILIARIES:
        return 0.19
    if lower in FUNCTION_WORDS:
        return 0.24 if word.istitle() else 0.02
    if lower in PERSONAL_PRONOUNS:
        return -0.03
    if lower in DEMONSTRATIVES:
        return 0.07
    if word == 'a':
        return -0.40
    if word == 'A':
        return 0.03
    if lower in ('today', 'now', 'then'):
        return 0.35
    if word in ('import', 'package', 'def'):
        return 0.44
    if word.isalpha() and not word.isascii():
        return -0.075
    return -0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        initial_run, previous, position, tail = True, '', 0, ''
    else:
        _, initial_run, previous, position, tail = carry
        position += 1
        initial_run = initial_run and token == previous

    if initial_run:
        value = boundary_value(token)
    elif token == ':' and position == 1 and previous == 'Title':
        value = -1.662
    elif token == ' ' and tail.endswith(r"\n"):
        value = -0.38
    elif token == ' <' and tail.endswith('#include'):
        value = -0.44
    elif token == '\r':
        value = -0.04
    else:
        value = -0.0015
    return (doc, initial_run, token, position, (tail + token)[-24:]), value

programs.haiku:
"""layers.1.mlp.down_proj:5985 -- a document-start detector.

This component is almost silent inside a document. Its activation is large only on the
FIRST token of a document (or of a packed row). At that position attention can see nothing
but the token itself, so the value depends only on which token it is.

The program predicts:
- first token is a bare line break that opens a comment or a markup/directive line
  ("//\\n", "#\\n", "//\\r\\n", "#\\r\\n", a lone "\\r", "<!", "@extends"): strongly negative (about -5);
- first token is the chat-template opener "<|im_start|>": mildly positive (+0.3);
- any other first token: a small negative (-0.09, the average first-token value);
- every other position: 0.

Everything else (the fine-grained token-by-token spread of first-token values, and the
small context effects inside documents) is not captured.
"""

READS = ()

LINE_BREAK_OPENERS = {"@extends", "<!", "//\n", "#\n", "//\r\n", "\r", "#\r\n", " #\r\n"}
CHAT_START = "<|im_start|>"


def step(carry, prefix, upstream):
    # A document starts at position 0 of a row and wherever the document id changes.
    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        return None, 0.0
    token = prefix.token_strings[-1]
    if token in LINE_BREAK_OPENERS:
        return None, -5.0
    if token == CHAT_START:
        return None, 0.3
    return None, -0.09

"""Clause-opening connectives: conjunctions, prepositions and auxiliaries that start a new
clause or phrase right after a comma, or a discourse connective that starts a sentence.

What it captures: this component fires on the word that joins a new clause to the one
before it. The strongest cases are a coordinating or subordinating word after a comma that
closes a full clause: "..., and", "..., but", "..., or", "..., with", "..., in", "..., by",
"..., that", "..., as", "..., because". A sentence-initial "And", "But", "Or", "Then",
"However", "Because" fires about as strongly. The word must follow a comma of a *long* clause:
after a short list item ("apples, pears, and") it stays near zero, because the component
switches on only once the clause before the comma has about five tokens. Auxiliaries
("is", "was", "not") after such a comma fire weakly. Pronouns after a comma ("it", "they")
go slightly negative. Everything else is predicted as 0.

The word lists come from inspecting the component's activations on training text.
"""
READS = ()

# Coordinating conjunctions, and their foreign-language equivalents.
COORDINATORS = {"and", "but", "or", "nor", "yet", "und", "et", "и", "pero", "mais", "y", "o"}
# Subordinating words and relative pronouns, and a few discourse connectives.
SUBORDINATORS = {
    "because", "when", "until", "unless", "while", "if", "as", "that", "where", "whose", "who",
    "whom", "whether", "since", "though", "although", "without", "through", "whereas",
    "then", "still", "instead", "however",
    "que", "qui", "che", "wie", "como", "als", "как", "such", "even", "than",
}
# Prepositions, and their foreign-language equivalents.
PREPOSITIONS = {
    "in", "on", "at", "by", "for", "with", "from", "of", "to", "about", "under", "over", "into",
    "during", "due", "rather", "between", "among", "against", "within", "upon", "via", "per",
    "par", "con", "en", "por", "pour", "dans", "à", "de", "в", "на", "с", "di", "des",
    "la", "le", "les", "el", "es", "se", "e", "ma", "il",
}
WORDS = COORDINATORS | SUBORDINATORS | PREPOSITIONS
# Auxiliary verbs, negation and a few adverbs; these fire weakly after a long clause's comma.
AUXILIARIES = {"is", "was", "are", "were", "be", "been", "will", "can", "do", "has", "have",
    "may", "would", "should", "could", "must", "not", "also", "all"}
# Connectives that open a sentence (after . ! ? or a newline).
DISCOURSE = {"and", "or", "but", "then", "however", "still", "meanwhile", "because", "such",
    "who", "where", "like", "yet", "also", "so", "thus", "unless", "when"}
# Connectives that appear mid-sentence without a comma before them.
MID_SENTENCE = {"then", "but", "however", "well"}
# Subject pronouns, which go slightly negative after a comma.
PRONOUNS = {"it", "they", "this", "these", "those"}
# Chinese connectives, which the tokenizer often merges with a preceding comma.
CHINESE = {"，并", "，而", "，但", "，且", "然后", "而", "且", "并", "以", "以及", "但是", "然而",
    "而且", "但"}
BREAKS = (",", ";", ".", "!", "?", ":", "\n")


def ramp(words):
    """0 for a one- or two-token item, rising to full strength at five tokens."""
    return min(1.0, max(0.0, (words - 2) / 2.5))


def step(carry, prefix, upstream):
    # carry: (document id, tokens since the last break, tokens before that break)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0)
    _, seg, closed = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if token in CHINESE:
        value = 1.0
    elif len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].rstrip()
        if before.endswith((",", ";")):
            if word in WORDS:
                value = ramp(closed)
            elif word in AUXILIARIES:
                value = 0.7 * ramp(closed)
            elif word in PRONOUNS:
                value = -0.2
        elif before.endswith((".", "!", "?", "\n")) or before == "":
            if word in DISCOURSE:
                value = 1.0
            elif word in WORDS:
                value = 0.4
        elif word in MID_SENTENCE:
            value = 0.4
    if token.rstrip().endswith(BREAKS):
        new = (doc, 0, seg)
    else:
        new = (doc, seg + 1, closed)
    return new, value

programs.sol:
"""Approximate single-letter word-opening pieces.

Token length, case, script and the previous token distinguish letter fragments
from ordinary words. English a/i, contractions and escapes are discounted;
word frequency discounts common standalone Cyrillic and Arabic letters.
Document openings, including repetitions of the initial token, use a separate
coarse baseline. Individual-token effects and longer fragments are not fitted.
"""
from functools import lru_cache
from wordfreq import zipf_frequency
import regex

READS = ()
SCRIPTS = {name: regex.compile(r'\p{Script=' + name + '}') for name in
           ('Latin', 'Cyrillic', 'Arabic', 'Greek', 'Devanagari', 'Katakana')}


@lru_cache(maxsize=2048)
def script(char):
    for name, pattern in SCRIPTS.items():
        if pattern.fullmatch(char):
            return name
    return ''


def predict(token, previous, initial):
    letters = ''.join(c for c in token if c.isalpha())
    if initial:
        if not letters:
            if token.isspace():
                return 1.9
            if token.isdigit():
                return 3.6 if token == '0' else 0.35
            return 1.5
        if not letters.isascii():
            return 0.25
        return -0.2 if len(letters) > 1 else 0.05

    # Contractions and literal escape sequences are not word openings.
    if token.startswith(("'", '’')) and token[1:].islower():
        return 0.0
    if token in (r'\n', r'\t', r'\r', r'\x'):
        return 0.0
    if token == r'\\':
        return -0.65

    # The n of a literal backslash-n can share a token with the next letter.
    if previous.endswith('\\') and token.startswith('n'):
        token = token[1:]
        letters = ''.join(c for c in token if c.isalpha())
        previous = '\n'
    if len(letters) != 1:
        if '\ufffd' in token and token.startswith(' '):
            return 0.35
        return 0.0

    char = letters[0]
    language = script(char)
    separated = token[0] != char
    boundary = separated or not previous or not previous[-1].isalpha()
    if language == 'Latin':
        if char.lower() in ('a', 'i'):
            return 0.04
        if char.isupper():
            if not separated and previous.isupper():
                return 0.0
            return 0.65 if '\n' in previous else 0.43
        if not boundary:
            return 0.0
        if '\n' in previous:
            return 0.55
        if not separated:
            return 0.05
        if not token[0].isspace():
            return 0.65
        if previous.isspace():
            return 0.10
        if char in 'aeiou':
            return 0.15
        return 0.43 if previous.strip().islower() else 0.25
    if language == 'Cyrillic':
        if not boundary:
            return 0.04
        frequency = zipf_frequency(char, 'ru')
        if frequency > 7.3:
            return 0.35 if char.islower() else 0.65
        return 0.90 if frequency > 6.4 else 1.5
    if language == 'Greek':
        greek_context = any(script(c) == 'Greek' for c in previous if c.isalpha())
        return 2.3 if boundary and greek_context else 0.10
    if language in ('Arabic', 'Devanagari'):
        if not boundary:
            return 0.05
        if language == 'Arabic' and zipf_frequency(char, 'ar') > 6.5:
            return 0.5
        return 1.7
    if language == 'Katakana':
        return 0.5
    return 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        previous, first, repeating = '', token_id, True
    else:
        _, previous, first, repeating = carry
        repeating = repeating and token_id == first
    value = predict(token, previous, repeating)
    return (doc, token, first, repeating), value

"""Approximate a negative-going pasture/fodder spelling feature.

Recognize grass, grazing, pasture, meadow, forage, manure, straw and feeding
at the token that completes their characteristic spelling. Related nature
words and lookalikes such as raff/paraff/graff also receive negative values.
This is not a general farming-topic detector: most tokens remain near zero.
A short word suffix handles split words; recent text disambiguates feed and
field. Agricultural Han characters have smaller negative responses too.
"""
import re

READS = ()


def predict_piece(piece, old_word, context):
    original_context = context
    context = context.lower()
    text = piece.lower()
    # Join a word split by the tokenizer, but not words separated by whitespace.
    joined = old_word + text if text[:1].isalpha() else text
    match = re.search(r'[^\W\d_]+$', joined)
    word = match.group() if match else ''
    value = 0.002

    if re.search(r'grass(?:y|es|h)?$', word):
        value = -2.5 if text.strip() == 'grass' else -3.0
        if text == 'ass':
            value = -4.0
    elif word.endswith(('grazing', 'graze')):
        value = -5.5
    elif word.endswith('grazed'):
        value = -2.8
    elif word.endswith('graz'):
        value = -2.5
    elif word.endswith(('pasture', 'pastures', 'pastured', 'meadow', 'meadows')):
        capitalized = piece.strip()[:1].isupper() or original_context.endswith('Me')
        value = -1.1 if capitalized and 'meadow' in word else -5.5
    elif word.endswith(('forage', 'forages')):
        value = -6.7
    elif word.endswith('foraging'):
        value = -3.3
    elif word.endswith(('manure', 'manured', 'manures')):
        value = -8.8
    elif word.endswith(('straw', 'straws')):
        split = text in ('aw', 'aws')
        upper = piece.strip()[:1].isupper()
        value = -5.8 if split or upper else -3.6
    elif word == 'chaff':
        value = -3.3
    # Subword lookalikes: the response stops before the rest of the word.
    elif text in ('aff', 'ff'):
        if word.endswith('paraff'):
            value = -6.5
        elif word.endswith('giraff'):
            value = -7.2
        elif word.endswith('graff'):
            value = -5.7
        elif word.endswith('raff'):
            value = -3.7
        else:
            value = -0.5 if text == 'aff' else 0.002
    elif (text in ('az', 'raz') and len(old_word) >= 3
          and old_word.endswith('r')):
        value = -2.0
    elif word.endswith('параз'):
        value = -3.1
    elif text == 'aw' and old_word.endswith('r'):
