"""Approximate an opening-position response, rather than general code detection.

Code-like words, quote/comment openers, emphasis and dot fillers get large
opening values. English sentence starters and text shape supply smaller biases.
An initial token repeated without other context retains its opening value;
after the opening run, predict the component's near-zero background instead.
"""
READS = ()


def opening(s):
    if s and set(s) == {'·'}:
        return 1.41
    if s == '<|endoftext|>':
        return 2.10
    if s in {'public', 'private', 'protected'}:
        return 4.2
    if s == 'void':
        return 3.1
    if s in {'char', 'uint', 'bool'}:
        return 1.8
    if s == 'int':
        return 0.69
    if s == 'default':
        return 2.17
    if s in {'const', 'def', 'print'}:
        return 1.05
    if s == 'package':
        return 0.56
    if s == '//\n':
        return 3.03
    if s.startswith(('"""', "'''")):
        return 1.7
    if s in {'\\"', '\\",', '.\\', '**', ' .'}:
        return 1.8
    if s.startswith('/*'):
        return 0.95
    if s in {'\\n', '\\t'}:
        return 0.86
    if s == 'The' or s in {'We', 'They', 'There'}:
        return 0.60
    if s in {'What', 'When', 'Which', 'How', 'Why', 'Where'}:
        return 0.75
    if s in {'A', 'This'}:
        return -0.22
    if s.isdigit():
        return 0.12
    if s.startswith('<|'):
        return 0.13
    if s.isspace():
        return 0.11
    if s == '.':
        return 0.31
    if s == '.\n':
        return 0.60
    if s.startswith(' '):
        return 0.14
    return 0.10


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        first, homogeneous = s, True
    else:
        first = carry[1]
        homogeneous = carry[2] and s == first
    value = opening(s) if homogeneous else -0.001
    return (doc, first, homogeneous), value

programs.haiku:
"""Layer 1 MLP down_proj component 5992: an opening-token detector for code and prose.

What it does
------------
The component is nearly silent. It speaks at the first token of a document, and at
positions where the document so far is one token repeated (for example a document that
opens with "^^^^" or "666"). There, attention sees nothing but the token itself, so the
activation depends only on which token it is. The program gives each such token a value
by its kind:

* bare declaration keywords of C, C++, Java, C# and Objective-C (public, private, void,
  bool, char, uint, static, interface, ...): 1.7 (the list's own values run 1.1 to 4.5);
* other bare programming keywords with no leading space (new, null, return, for, def,
  trait, ...): 0.7;
* annotations (@Override, @interface, @extends): 1.5;
* a comment or docstring marker that ends its line (//, #, /*, triple quotes): 1.5;
* a few other opening symbols: an HTML doctype "<!" (5.0), bold "**" (1.7),
  an escaped quote (1.9) and the dotted leader "··" (1.4);
* common English words that open a sentence (The, They, We, There, When, What,
  How, Which, No, ...): 0.6;
* any other opening token: 0.1, a small positive value.

Everywhere else the program predicts 0. That is nearly right: elsewhere the activation
is small noise (typical size 0.04) with no simple pattern.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Bare declaration keywords of C-family and Java-like languages.
DECLARATION_WORDS = {
    "public", "private", "protected", "static", "void", "bool", "boolean", "char",
    "uint", "int", "long", "float", "double", "unsigned", "final", "const",
    "constexpr", "virtual", "default", "interface", "class", "struct", "enum",
    "typename", "template", "namespace", "ostream", "istream", "string",
    "VOID", "BOOL", "Void",
}

# Keywords of other programming languages, bare (no leading space).
PROGRAM_WORDS = {
    "new", "null", "return", "for", "while", "break", "try", "def", "super", "trait",
    "impl", "crate", "await", "async", "let", "mut", "package", "export", "import",
    "extends", "implements", "print", "echo", "where", "unsafe", "delete", "set",
    "get", "auto", "byte", "volatile", "sealed", "throws", "var", "function",
}

# Common English words that open a sentence in prose.
SENTENCE_WORDS = {
    "The", "They", "We", "I", "He", "There", "Here", "Now", "When", "Where",
    "What", "How", "Which", "Who", "That", "No", "Some", "Any", "Every",
}

# Comment and docstring markers that open a line (with the line break or triple quote).
LINE_MARKERS = {'"""', '"""\n', "'''", "'''\n", "/**", "/*\n", "//\n", "#\n"}

# Other symbols seen opening a document, with their values.
OTHER_OPENERS = {"<!": 5.0, "**": 1.7, '\\"': 1.9, "··": 1.4}

OPENING_VALUE = 0.1
DECLARATION_VALUE = 1.7
PROGRAM_VALUE = 0.7
SENTENCE_VALUE = 0.6
ANNOTATION_VALUE = 1.5
LINE_MARKER_VALUE = 1.5


def _value(text: str) -> float:
    """The activation an opening token gets, by its kind."""
    if text in DECLARATION_WORDS:
        return DECLARATION_VALUE
    if text in PROGRAM_WORDS:
        return PROGRAM_VALUE
    if text in SENTENCE_WORDS:
        return SENTENCE_VALUE
    if text in LINE_MARKERS:
        return LINE_MARKER_VALUE
    if text in OTHER_OPENERS:
        return OTHER_OPENERS[text]
    if text.startswith("@") and text[1:2].isalpha():
        return ANNOTATION_VALUE
    return OPENING_VALUE


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        opening = True  # first token of a document (or of a row)
    else:
        # still a run of this same token since the document began?
        opening = bool(carry) and prefix.token_ids[t] == prefix.token_ids[t - 1]
    value = _value(prefix.token_strings[t]) if opening else 0.0
    return opening, value

