"""Approximate rare clause-introducing and naming constructions.

Negative excursions mark Chinese narrative/reporting openers and English
expressions such as 'turns out', 'except that', and 'what happened is'.
Naming expressions ('denoted by', 'known as') have the opposite sign.
Typography, filename suffixes, and sentence/document beginnings have
separate surface-form responses. These rules deliberately omit most of the
small, token-specific variation.
Everything else gets a small near-zero background. State is document-local.
"""
import re
import regex

READS = ()
TRADITIONAL = str.maketrans('說見話據卻還傳', '说见话据却还传')
CONFIG_SUFFIXES = frozenset({
    '.json', '.yaml', '.yml', '.xml', '.ini', '.cfg', '.conf',
})
BUILD_SUFFIXES = frozenset({'.mod', '.out', '.jar', '.zip'})
BOUNDARIES = '，,。；;：:\n！？!?“”「」'
DISCOURSE_OPENERS = frozenset({
    'In', 'On', 'At', 'To', 'For', 'From', 'With', 'During',
    'Before', 'After', 'Since', 'Until', 'Also', 'However',
    'Moreover', 'Therefore', 'Thus', 'Meanwhile',
})
SENTENCE_SUBJECTS = frozenset({
    'The', 'A', 'An', 'This', 'That', 'These', 'Those',
    'It', 'He', 'She', 'They', 'We',
})


def response(token, previous):
    word = token.strip()
    before = previous.rstrip()
    last = before[-1:] if before else ''
    chinese = word.translate(TRADITIONAL)
    prior = before.translate(TRADITIONAL)
    boundary = bool(last and last in BOUNDARIES)

    # Chinese presentatives, reporting, and narrative transitions.
    if chinese in {'只见', '忽见'}:
        return -1.12
    if chinese == '话说':
        if prior.endswith(('没', '狠')):
            return -0.03
        return -0.85 if boundary or last == '(' else -0.50
    if chinese == '见':
        if regex.search(r'\p{Hiragana}|\p{Katakana}', before[-80:]):
            return 0.0
        if prior.endswith(('只', '却')):
            return -1.03
        if prior.endswith(('就', '忽', '便')):
            return -0.85
        if boundary:
            return -0.50
        return 0.01
    if chinese == '说':
        if prior.endswith(('且', '却')):
            return -1.30 if prior.endswith('且') else -1.0
        if prior.endswith(('据', '就')):
            return -0.60
        if prior.endswith(('还', '是')):
            return -0.40
        if boundary:
            return -0.57
        if prior.endswith(('不', '没', '想', '小说', '对', '跟我', '小')):
            return -0.01
        return -0.12
    if chinese == '留下':
        if prior.endswith('只'):
            return -0.80
        return -0.43 if boundary else -0.10
    if chinese == '忽' and boundary:
        return -0.36
    if chinese == '慌':
        return -0.50 if boundary else (-0.02 if prior.endswith('惊') else -0.22)

    # Completed English constructions, not isolated content words.
    lower = before.lower()
    w = word.lower()
    if w in {'is', 'was', 'wasn', 'isn', 'that', 'the'}:
        if re.search(
            r'\bwhat\b[^.!?\n]{0,65}\bhappen(?:s|ed|ing)'
            r'\s*(?:here[, ]*)?(?:(?:is|was)\s*)?$', lower
        ):
            if w in {'is', 'was', 'wasn', 'isn'}:
                return -0.74
            if re.search(r'\b(?:is|was)\s*$', lower):
                return -0.78 if w == 'that' else -0.16
        if w == 'that' and re.search(r'\bexcept$', lower):
            return -0.48
        if w == 'that' and re.search(r'\bhappen(?:s|ed)$', lower):
            return -0.40
        if w == 'that' and re.search(r'\bturn(?:s|ed)? out$', lower):
            return -0.37
        if w == 'that' and re.search(r'\b(?:is|was|see|found|notice|realized)$', lower):
            return -0.16
    if w == 'out' and re.search(r'\bturn(?:s|ed)?$', lower):
        return -0.48 if lower.endswith('turns') else -0.25
    if w == 'to' and re.search(r'\bhappened$', lower):
        return -0.08
    if w == 'oted' and re.search(r'\bden$', lower):
        return 0.35
    if w in {'by', 'as'} and lower.endswith('denoted'):
        return 0.53
    if w == 'as' and re.search(r'\bknown$', lower):
        return 0.27
    if w == 'called' and re.search(r'\b(is|are|also|often|commonly)$', lower):
        return 0.17

    if word == '¶':
        if previous.endswith(':\n'):
            return 0.60
        return 0.20 if previous.endswith('\n') or last == '[' else 0.03
    if len(word) >= 2 and set(word) == {'·'}:
        return -0.46
    if word in CONFIG_SUFFIXES or word in BUILD_SUFFIXES:
        return -0.25
    # Document openings, including conventional source-code openers.
    if not previous:
        if word == '<|endoftext|>':
            return -1.04
        if word in {'def', 'function'}:
            return -1.0
        if word in {'using', 'export'}:
            return -0.60
        if word == 'import':
            return 0.34
        if word == '#include':
            return -0.30
        return -0.13 if not word else -0.05
    if last in '.!?\n' and (token[:1].isspace() or previous.endswith('\n')):
