"""A spelling contrast in Czech/Slovak and Hungarian-looking text.

Completed words supply a decaying language preference using corpus word
frequencies. Outside these languages the prediction is nearly zero. Inside,
short token spellings containing e/g/j tend negative, whereas i, initial u,
and several accented vowels tend positive. Word starts and the preceding
piece of an unfinished word modify that contrast. This is an approximation,
not a dictionary of token activations or an exact language recognizer.
"""
from functools import lru_cache
from math import exp
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = (
    'hu', 'cs', 'sk', 'en', 'de', 'fr', 'es', 'it', 'pt',
    'pl', 'nl', 'sv', 'tr', 'fi', 'sh', 'sl', 'ro',
)
ALPHABET = set('abcdefghijklmnopqrstuvwxyzáéíóöőúüűýčďěňřšťůžľĺŕ')
LETTER_SCORE = {
    'e': -1.17, 'g': -1.07, 'j': -0.67, 'v': -0.49,
    'z': -0.28, 'i': 0.53, 't': 0.20, 'r': 0.10,
    'č': -0.77, 'á': 0.23, 'ú': 0.69, 'ó': 0.48, 'ü': 0.54,
}
WORD_START = {'e': -0.85, 'o': -0.58, 'i': 0.53, 'u': 0.76, 't': 0.37}


def sigmoid(x):
    return 1.0 / (1.0 + exp(-max(-50.0, min(50.0, x))))


@lru_cache(maxsize=50000)
def language_evidence(word):
    frequencies = tuple(zipf_frequency(word, lang) for lang in LANGUAGES)
    best = max(frequencies)
    return tuple(f - best for f in frequencies)


@lru_cache(maxsize=50000)
def spelling(token):
    word = ''.join(c for c in token.lower() if c in ALPHABET)
    n = len(word)
    if not n:
        return 0.0, (0.0, 0.0, 0.0)
    divisor = max(1.0, n / 3.0)
    score = sum(LETTER_SCORE.get(c, 0.0) for c in word) / divisor
    score += 0.045 * min(n, 8)
    score += {'h': 0.75, 'u': 0.96}.get(word[0], 0.0)
    score += {'o': -0.80, 'r': 0.70}.get(word[-1], 0.0)
    if token[0].isspace():
        score += 0.10
        score += sum(WORD_START.get(c, 0.0) for c in word) / divisor
        if n == 1:
            score += {'i': 1.34, 'u': 1.09}.get(word, 0.0)
    previous = tuple(word.count(c) / divisor for c in 'eou')
    return score, previous


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc or token.startswith('<|'):
        scores = (0.0,) * len(LANGUAGES)
        word = ''
        previous = (0.0, 0.0, 0.0)
    else:
        _, scores, word, previous = carry

    for c in token.lower():
        if c.isalpha() and ord(c) < 512:
            word += c
        else:
            if len(word) >= 2:
                evidence = language_evidence(word)
                scores = tuple(0.9 * s + e for s, e in zip(scores, evidence))
            word = ''

    preference = max(scores[:3]) - max(scores[3:])
    gate = sigmoid(preference - 6.0)
    # A modestly larger spelling contrast in Hungarian than Czech/Slovak.
    hungarian = sigmoid(scores[0] - max(scores[1:3]))
    gate *= 0.92 + 0.34 * hungarian

    value, next_previous = spelling(token)
    if token and token[0].isalpha():
        e, o, u = previous
        value += -0.57 * e - 0.20 * o + 0.28 * u
    return (doc, scores, word, next_previous), float(gate * value)

