import re

READS = ()


def predict(token, before, first):
    s = token.strip()
    low = s.lower()
    tail = before.lower()

    # Dataset-style title fields have a particularly strong negative colon.
    if token == ':' and before == 'Title':
        return -2.74
    if first:
        if token == 'public':
            return 2.98  # Java visibility declaration
        if token == 'Mc':
            return 1.10  # beginning of a Mc- surname
        if token == 'theorem':
            return 0.59

    # A line-opening '1' is a possible first numbered-list item.
    if token == '1':
        if first:
            return 0.32
        if '\n' in before and not before.rsplit('\n', 1)[-1].strip():
            indent = before.rsplit('\n', 1)[-1]
            if indent:
                return 0.04
            return 0.55 if '：' in before[-8:] else 0.24
        if tail.endswith('\\n'):
            return 0.30

    # Separate pieces of indefinite pronouns, not ordinary word endings.
    if low in {'thing', 'body', 'one', 'where', 'ody'}:
        stem = re.search(r'\b(some|every|any|no|else|someb)\s*$', tail)
        if stem:
            root = stem.group(1)
            if low == 'one':
                if root == 'some':
                    return 0.56
            elif low == 'where' and root in {'some', 'every', 'any', 'no', 'else'}:
                return 0.65 if token.startswith(' ') or root == 'else' else 0.30
            elif low in {'thing', 'body', 'ody'} and root != 'else':
                return 0.67 if token.startswith(' ') else 0.35
    if low == 'eth' and tail.endswith(' som'):
        return 0.61
    if token == 'in' and tail.endswith(' someth'):
        return 0.72
    if low == 'one' and re.search(r'\b(?:each|which)\s*$', tail):
        return -0.45
    if low == 'of':
        if re.search(r'\b(?:each|which|every|any) one\s*$', tail):
            return -0.74
        if re.search(r'\bno amount\s*$', tail):
            return -1.00

    # Passive publication notices in blog and course-document footers.
    if low in {'posted', 'uploaded'} and tail.endswith(' was'):
        if re.search(r'\b(?:entry|note) was$', tail):
            return 1.00 if low == 'uploaded' else 0.84

    # Chinese quantification: 一 is 'one'; these modifiers bind it tightly.
    if s.startswith('同一'):
        return -0.48
    if s.startswith(('这一', '這一')):
        return -0.35
    if s.startswith(('每一', '另一', '另一个', '另一個')):
        return -0.32
    if s.startswith('一') and before:
        if before[-1] in '同任':
            return -1.55
        if before[-1] == '每':
            return -0.95
        if before[-1] in '哪某另又这那上下前后':
            return -0.52

    # Thai nasal consonants and h+n clusters, with local spelling context.
    if s == 'หน':
        if before.endswith(('โ', 'เ', 'แ')):
            return 0.45
        if before.endswith(('คน', 'ส่วน', 'อย่าง')):
            return 1.50
        return 1.08
    if s == 'น':
        if before.endswith(('ดัง', 'ตอน', 'อย่าง', 'แบบ')):
            return 0.88
        # A leading Thai vowel before the preceding consonant makes n
        # likely to end a syllable rather than begin the next one.
        if re.search(r'[เแโใไ][ก-ฮ]{1,2}$', before):
            return 0.03
        consonant = (before and before[-1].isalpha()
                     and before[-1] not in 'ะาำเแโใไฤฦ')
        return 0.30 if consonant else 0.10
    if s == 'ง':
        if before.endswith('ไ'):
            return 0.91
        if before.endswith(('หนึ่', 'นึ่', 'อย่าง')):
            return 0.72
        return 0.07
    if s == 'ึ' and before.endswith('หน'):
        return 0.72
    if s == 'ัง' and before.endswith('หน'):
        return 1.18
    if s in {'ัง', 'ัก'} and before.endswith('หล'):
        return 0.65
    if s == 'ึง' and before.endswith('น'):
        return 1.25
    if s == 'ี้' and before.endswith('หน'):
        return 0.62

    if low == 'modified' and re.search(r'\blast$', tail):
        return -0.62
    if token == '··' and before.endswith('··'):
        return 0.244 if before.endswith('··' * 4) else 0.0
    if token == ' ':
        if before.endswith(('\\n', '\\n\\n')):
            return -0.12
        if before.endswith('\n'):
            return -0.05
        if before.endswith('.'):
            return 0.03
        return -0.005
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ''
        first = True
    else:
        before = carry[1]
        first = False
    token = prefix.token_strings[-1]
    value = predict(token, before, first)
    return (doc, (before + token)[-100:]), value

