"""Draft 2: four small rules with class-mean values (activation units)."""
READS = ()

DOC_START = 0.05        # first token of a document: mean activation there
LINE_NUMBER = 0.06      # a digit starting a line, e.g. list item "1."
THAI_WORD_PIECE = 0.45  # Thai syllables น / ง / หน, as in นั้น, ยังไง, หนึ่ง
OF_AFTER_QUANTIFIER = -0.05  # " of" after "one", "each", "any", ...

THAI_WORD_PIECES = {"น", "ง", "หน"}
QUANTIFIERS = {" one", " each", " any", " which", " amount"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOC_START
    prev = prefix.token_strings[-2]
    if tok.isdigit() and prev.strip() == "" and "\n" in prev:
        return None, LINE_NUMBER
    if tok in THAI_WORD_PIECES:
        return None, THAI_WORD_PIECE
    if tok == " of" and prev in QUANTIFIERS:
        return None, OF_AFTER_QUANTIFIER
    return None, 0.0

