"""A token-ending detector for 分, the 'part/share/minute' morpheme.

Compounds about contents or shares respond more strongly than ordinary parts.
A number immediately before 分 usually makes it a minute/point unit, with a
smaller response. Japanese nonnumeric uses are stronger. Related Chinese
characters, Korean 분, Vietnamese phân/phần, and split ph + en/an spellings
are included, along with weak fraction vocabulary responses. A separate rule
recognizes a document-opening 'Title:' label. Most background activity is
left at zero.
These are approximate lexical rules, not a complete semantic analysis.
"""
import regex as re

READS = ()
KANA = re.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position, previous = '', 0, ''
    else:
        _, tail, position, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    last = tail[-1:]
    value = 0.0

    if word == '分':
        value = 3.6
        if last.isnumeric():
            value = 2.3
        elif last in ('気', '气'):  # mood/feeling
            value = 9.0
        elif last in ('糖', '水', '油', '養', '养', '成'):  # contents
            value = 7.0
        elif last in ('充', '身', '过', '過'):
            value = 7.5
        elif last in ('月', '年', '日') and KANA.search(tail):
            value = 7.0
        elif KANA.search(tail):
            value = 5.3
        if position == 0:
            value = 2.5
    elif word.endswith('分'):
        value = 2.3
        if word in ('水分', '成分'):
            value = 6.0
        elif word == '充分':
            value = 3.5
        elif word in ('得分', '积分', '積分', '比分', '加分'):  # scoring
            value = 3.5
        elif word in ('过分', '過分'):
            value = 5.4
        elif word == '自分':  # oneself
            value = 0.8
        elif word.endswith('部分'):
            value = 1.5 if len(word) <= 2 or word == '的部分' else 0.2
        elif word in ('区分', '细分', '細分', '划分', '劃分', '评分', '評分'):
            value = 0.9
        elif len(word) > 2:
            value = 0.3
    elif word.endswith('份'):
        value = 1.5
        if word == '份':
            value = 3.6
            if last in ('充', '过', '過', '身'):
                value = 7.5
            elif last.isnumeric():
                value = 1.5
        elif word in ('成份', '水份'):
            value = 6.0
        elif word == '股份':  # financial shares
            value = 7.0
        elif word.endswith('身份'):
            value = 3.2
        elif word in ('月份', '省份', '备份', '備份'):  # month/province/backup
            value = 0.0
    elif word in ('氛', '气氛', '氣氛'):
        value = 3.3
    elif word in ('纷', '紛', '纷纷', '紛紛'):
        value = 1.2
    elif word.endswith('분'):
        value = 3.2 if len(word) < 3 else 0.0
        if word == '분' and last in ('기', '충', '수'):
            value = 6.3
        elif word == '분' and last == '구':
            value = 0.0
    elif lower == 'phân':
        value = 6.0
    elif lower == 'phan' and not last.isalpha():
        value = 5.0
    elif lower == 'phần':
        value = 3.7
    elif token == word and lower in ('en', 'eno', 'én', 'än', 'an', 'án'):
        if tail.lower().endswith(('ph', 'pha')):
            value = 2.8
            if lower == 'an':
                at_word_start = re.search(r'(^|[^a-z])ph$', tail.lower())
                value = 6.3 if at_word_start else 2.0
    elif (token == word and lower in ('hen', 'han')
          and tail.lower().endswith(('ip', 'op'))):
        value = 2.5
    elif word == 'ん' and last in ('ふ', 'ぶ'):
        value = 4.0 if last == 'ふ' else 6.5
    elif lower in ('frac', 'half', 'difference', 'differences', 'separate'):
        value = 0.27
    elif lower in ('fraction', 'fractions', 'part', 'parts'):
        value = 0.10

    if position == 1 and previous == 'Title' and word == ':':
        value = 5.3
    return (doc, (tail + token)[-96:], position + 1, token), value

"""Local spelling cues at subword boundaries, mostly around nasal m/n.

Positive cues include short 'ok' continuations and nasal consonant clusters;
'ek' and several doubled-nasal/front-vowel spellings give negative values.
Transliteration shares these rules across scripts. A few syllabic-script
rules handle vowel marks and split Tamil conjuncts. Ordinary tokens get
nearly zero. These are coarse local estimates, not a model of word meaning.
"""
import unicodedata as ud
import regex as re
from anyascii import anyascii

READS = ()
BASE = -0.001
TAMIL_CONJUNCT = '்'.encode() + b'\xe0\xae'


def response(prev, cur, previous_bytes, current_bytes):
    if not prev or not cur or cur[0].isspace():
        return BASE
    if re.search(r'\p{Script=Han}', prev + cur):
        return BASE
    # A pulli suppresses a Tamil consonant's inherent vowel. Its following
    # consonant can be split between this token and the next one.
    if current_bytes == TAMIL_CONJUNCT:
        return -2.0
    if previous_bytes.endswith(TAMIL_CONJUNCT):
        if 0x80 <= current_bytes[0] < 0xc0:
            return -2.3
    p, s = anyascii(prev).lower().strip(), anyascii(cur).lower()
    if not p or not s:
        return BASE
    if re.search(r'\p{Script=Hangul}', cur) and s == 'nae':
        if p in ('a', 'in'):
            return -2.5 if p == 'a' else -6.5
    if re.search(r'\p{Script=Greek}', prev) and p == 'm':
        if s in ('i', 'o'):
            return 0.95
    if re.search(r'\p{Script=Thai}$', prev) and p[-1] in 'mn':
        if ud.category(cur[0]).startswith('M'):
            return 0.45
    # Multiple vowel diacritics, hooks, dots and horns identify Vietnamese
    # vowel pieces following a separately tokenized nasal onset.
    decomposed = ud.normalize('NFD', cur[0])
    marks = [c for c in decomposed if ud.combining(c)]
    if p in ('m', 'n') and decomposed[0].lower() in 'aeiouy':
        if len(marks) > 1 or any(c in '\u0309\u0323\u031b\u0306' for c in marks):
            return 0.8
    if p[-1] in 'mn':
        if s == 'ms':
            return 5.0
        if s == 'mp':
            return 4.1
        acronym = cur.isupper() and prev.strip(' ._/-(').isupper()
        if acronym and s == 'ft':
            return 4.7
        if acronym and s in ('md', 'ml', 'mr'):
            return 2.3
        if re.fullmatch(r'ok[ou]?', s):
            return 3.6 if p[-1] == 'm' or acronym else 0.65
        if s.startswith('ek') and len(s) <= 3:
            return -0.85
        if s in ('iko', 'ink'):
            return 1.55
        if p.endswith(('om', 'em')) and s.startswith(('ma', 'me')):
            if len(s) <= 3:
                return -1.5
        if p in ('in', 'en') and s.startswith(('na', 'ne')):
            return -1.3
        if re.search(r'([mn])\1$', p) and len(s) <= 2:
            if s[0] in 'aei':
                return -0.5
        if s.startswith('ak') and len(s) <= 3:
            return -0.3
        if s == 'och':
            return 1.05
        if s == 'ech':
            return -0.3
        if s == 'no' and p[-1] == 'm':
            return 1.2
        if s in ('ma', 'me'):
            return -0.4
        if s == 'min' and p.endswith('am'):
            return 0.65
    if re.search(r'[mn]e$', p) and s in ('k', 'ch'):
        return -1.0
    return BASE


def step(carry, prefix, upstream):
    t = prefix.position
    if not t or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, BASE
    prev, cur = prefix.token_strings[-2:]
    # Java's reverse-domain package header, at the start of a document.
    first = t == 1 or prefix.document_ids[-2] != prefix.document_ids[-3]
    if first and prev == 'package' and cur == ' com':
        return None, 2.0
    return None, response(prev, cur, *prefix.token_bytes[-2:])

"""Mostly an age/elapsed-time signal, with a smaller spelling signal.

Age words produce negative values, strengthened by local constructions like
'at age', 'the age of', 'how old', 'grew up', and 'when I was'. Word
boundaries distinguish age from endings of unrelated words such as package.
The positive rules concern short Greek/Cyrillic vowel-initial fragments.
A few formatting rules cover A-number references and document openings.
These rules approximate the main patterns, not every lexical association.
Only a short byte suffix is remembered; documents reset it completely.
"""
import re
import unicodedata as ud

READS = ()
AGE = {'age': -5.4, 'aged': -7.4, 'ages': -5.0,
       'aging': -4.2, 'ageing': -4.2,
       'âge': -5.8, 'âges': -5.0, 'âgé': -3.2}
TIME = {'ago': -2.0, 'old': -0.5, 'older': -0.5, 'oldest': -0.5,
        'era': -2.7, 'eras': -4.2, 'generation': -0.4,
        'generations': -0.4, 'generational': -3.5,
        'intergenerational': -3.5}
AGE_LIMIT = r'\b(at|by|under|over|before) the'


def last_word(text):
    match = re.search(r'[^\W\d_]+$', text)
    return match.group().lower() if match else ''


def predict(before, token):
    text = (before + token)[-160:]
    low = text.lower()
    prev, word = last_word(before), last_word(text)
    value = 0.0
    if token and token[-1].isalpha():
        lead = low[:-len(word)].rstrip()
        value = AGE.get(word, TIME.get(word, 0.0))
        if word == 'age':
            if re.search(r'\bat$', lead):
                value = -10.7
            elif re.search(AGE_LIMIT + '$', lead):
                value = -8.3
            elif re.search(r'\bthe$', lead):
                value = -6.1
            elif re.search(r'\bof$', lead):
                value = -3.7
            elif before.endswith('\n') and token == 'Age':
                value = -7.8
            if token.strip() == 'AGE':
                value = -4.2
        elif word == 'aged':
            if lead.endswith('('):
                value = -11.0
            elif lead.endswith('school-'):
                value = -10.0
            elif lead.endswith('middle-'):
                value = -4.2
        elif word == 'ages' and re.search(r'\bmiddle$', lead):
            value = -0.4
        elif word == 'ago':
            if prev in ('time', 'long', 'while', 'year'):
                value = -4.1
            elif prev in ('month', 'months', 'week', 'weeks', 'day', 'days'):
                value = -0.9
        elif word == 'old':
            if prev in ('how', 'too', 'as'):
                value = -3.8
            elif prev in ('year', 'years', 'same'):
                value = -1.6
        elif word == 'generation' and prev == 'new':
            value = -2.2
        elif word in ('era', 'eras') and prev in (
                'non', 'que', 'egli', 'no', 'yo', 'ella', 'ele', 'como'):
            value = 0.0  # Avoid some Romance-language uses of the verb era.
        elif word == 'was':
            value = -0.5 if prev == 'i' else 0.0
            if re.search(r'\bwhen(?:\s+\w+){0,3}\s+was$', low):
                value = -3.9 if prev == 'i' else -2.5
                if prev in ('it', 'there'):
                    value = -0.3

        # Spelling side: the first one or two letters of a word.
        plain = ''.join(c for c in ud.normalize('NFD', word)
                        if not ud.combining(c))
        if plain and plain[0] in 'αε' and len(plain) <= 2:
            if len(plain) == 2:
                value = 2.2
            elif word in ('έ', 'ἀ') and token[-1].islower():
                value = 5.4
            elif word != plain:
                value = 2.0
            else:
                value = 0.3 if plain == 'α' else 0.9
        if (len(word) == 2 and word[0] == 'а'
                and 'CYRILLIC' in ud.name(word[1], '')
                and word[1] not in 'аеёиоуыэюя'):
            value = 0.8
        if word in ('ав', 'ов', 'ев'):
            value = 4.1 if word[0] == 'е' else 1.7
        if word == 'асс':
            value = 5.7 if token == 'сс' else 0.8
        if token.lower() == ' ess':
            value = 2.3

    # Responses carried onto a following grammatical token or numeric gap.
    if token.lower() == ' of':
        if prev == 'age':
            value = -7.8 if re.search(
                AGE_LIMIT + ' age$', before.lower()) else -4.0
        elif prev == 'ages':
            value = -4.1
        elif prev in ('era', 'eras'):
            value = -2.2
        elif prev in ('son', 'daughter', 'mother', 'father', 'child', 'friend'):
            value = -1.0
        elif prev == 'died':
            value = -1.6
        elif prev == 'as':
            value = -0.7
    if token == ' ':
        value = {'age': -4.8, 'aged': -2.2, 'at': -1.0,
                 'under': -0.8, 'was': -0.8}.get(prev, 0.0)
        if before.endswith(('At', 'AT', 'Under')):
            value = -2.8 if prev == 'at' else -2.0
        elif re.search(r'\bage of$', before.lower()):
            value = -2.3
        elif prev in ('born', 'since', 'until', 'early', 'late'):
            value = -0.45
    if token == ' up' and prev in ('grew', 'grow', 'grown', 'growing', 'grows'):
        value = -2.3 if prev == 'grew' else -1.7
    if token == ' than' and prev in ('younger', 'older'):
        value = -2.1 if prev == 'younger' else -0.8
    if token == ' as' and prev in ('young', 'old', 'early'):
        value = -2.5 if prev == 'young' else -1.6
    if token == '1' and re.search(r'\bage $', before.lower()):
        value = -4.0 if before.endswith('Age ') else -2.5
    if token and text.endswith(('龄', '齢')):
        value = -12.0 if text[-2:-1] == '年' else -8.5

    # Alphanumeric identifiers and recognizable formatting at document starts.
    if token.isascii() and token.isdigit() and re.search(r'\bA$', before):
        value = 1.6
    if token == ':' and re.search(r'(?:^|<\|endoftext\|>)Title$', before):
        value = 3.37
    if token == '//\n' and (not before or before.endswith('<|endoftext|>')):
        value = -4.43
    if token == '··' and before.endswith('··'):
        value = -2.29
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (None, b'')
    if old_doc != doc:
        tail = b''
    before = tail.decode('utf-8', errors='ignore')
    joined = tail + prefix.token_bytes[-1]
    # Decode joined bytes to recognize letters split across token boundaries.
    token = joined.decode('utf-8', errors='ignore')[len(before):]
    return (doc, joined[-640:]), predict(before, token)

