"""layers.1.mlp.down_proj:6009 -- the "age of a person" feature.

This component is switched on (negatively) by the word for a person's age and by the
spot where an age number is about to come: "at age [ ]9", "the age [of] 74", "aged 28",
"Age [ ]11", "when I [was] 9". It is also weaker on "years ago", "3 years old",
"era", and age words in other languages (年龄, 龄, 岁, età, edad). Everything else is
near zero, so the program predicts 0 there.

Plain rules, no table of token ids:
  1. the word age/aged/ages/aging/Age (with a leading space or capital) -> -5.5
  2. the token right after such a word, when it is a space, "of" or "at" -> -4.5
  3. "ago" / "old" after a time unit (years, days, ...) -> -1.8; other "old"/"ago" -> -0.7
  4. "was" within three tokens after "when" -> -2.0
  5. "era" -> -2.0; age words in Chinese, Italian, Spanish -> their own small values

The program reads only the tokens so far and the document id, as the model does.
"""
READS = ()

AGE_WORDS = {"age", "aged", "ages", "aging", "ageing", "Age", "AGE"}
AGE_OTHER = {"龄": -8.0, "年龄": -2.6, "岁": -0.9, "歲": -0.9, "età": -3.6, "edad": -1.2}
AGE_SLOT = {" ", " of", " at"}
TIME_UNITS = {"years", "year", "days", "months", "weeks", "hours", "yrs"}
ERA_WORDS = {" era", " ERA", " Era", "-era"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    tok = toks[-1]
    same = len(toks) > 1 and docs[-2] == docs[-1]  # previous token is in this document
    prev = toks[-2] if same else ""
    word = tok.strip()

    if (tok[:1] in (" ", "-") or tok[:1].isupper()) and word in AGE_WORDS:
        return carry, -5.5  # "age", "aged", "Age"
    if word in AGE_OTHER:
        return carry, AGE_OTHER[word]
    if same and prev.strip() in AGE_WORDS and tok in AGE_SLOT:
        return carry, -4.5  # the blank before the number: "age [of] 74", "Age [ ]11"
    if tok in (" ago", " old", " Ago") and same and prev.strip() in TIME_UNITS:
        return carry, -1.8  # "five years ago", "3 years old"
    if tok in (" ago", " old", " Old", " Ago"):
        return carry, -0.7
    if tok == " was" and any(x.strip().lower() == "when" for x in toks[-4:-1]):
        return carry, -2.0  # "when I [was] 9"
    if tok in ERA_WORDS:
        return carry, -2.0
    return carry, 0.0

programs.sol:
"""A document-onset and typography approximation.

The main effect is a negative pulse at a document's first token, stronger for
unspaced familiar English words. Lowercase underscore-prefixed identifier
fragments instead give a positive pulse. Declaration keywords are strongly
negative. The onset pulse persists through exact repetitions of the initial
token. Elsewhere predict zero, except for nonbreaking spaces. Initial
middle-dot leaders receive a strong negative pulse. Word-specific and
encoding spikes remain unexplained.
"""
import unicodedata
from wordfreq import zipf_frequency

READS = ()
DECLARATIONS = {'class', 'def', 'function', 'var', 'const', 'package'}


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    s = prefix.token_strings[-1]
    word = s.strip()
    if first:
        if s == '··':
            value = -2.40
        elif s.startswith('_') and s[1:].isalpha():
            value = 0.70 if s[1:].islower() else -0.10
        elif s in DECLARATIONS:
            value = -1.90
        elif s.startswith(' '):
            if word.lower() in {'a', 'e', 'i', 'o', 'u'}:
                value = 0.03
            elif word and all(unicodedata.category(c).startswith('P')
                              for c in word):
                value = -0.57
            else:
                value = -0.31
        elif zipf_frequency(word.lower(), 'en') > 2.5:
            value = -0.62 if word.isascii() and word.isalpha() else -0.48
        else:
            value = -0.31 if len(word) <= 10 else -0.59
        return (prefix.token_ids[-1], value), value
    if carry is not None and prefix.token_ids[-1] == carry[0]:
        return carry, carry[1]
    if '\u00a0' in s:
        value = 0.05
    else:
        value = 0.0
    return None, value

"""A Ruby-source detector, with different responses to its syntactic roles.

Require-and-a-quote, colonless class/def headers, Ruby iterators and
accessors establish the language. In that context, block delimiters,
predicate suffixes, definitions and constructors are especially strong.
Ordinary names are weak; comments and string contents suppress structure.
Distinctive lexical forms retain fixed responses even outside that context.
A small negative correction applies at document starts. This is only an
approximate lexer, and does not explain all the weak unrelated activations.
"""
import re

READS = ()
# Extra response to familiar Ruby keywords once source has been recognized.
KEYWORDS = {
    'def': 6.3, 'class': 5.2, 'module': 5.5, 'end': 6.8,
    'do': 9.5, 'initialize': 8.0, 'else': 4.2, 'if': 3.1,
    'nil': 1.8, 'require': 3.1, 'puts': 4.2, 'unless': 3.0,
    'true': 1., 'false': 1., 'return': 1., 'self': 1.,
    'super': 1., 'yield': 1., 'rescue': 1.,
}
BASE = {
    'do': -.24, 'else': -.18, 'unless': -.1, 'nil': -.08,
    'initialize': .6, 'Ruby': 2.2, 'ruby': .3,
    'Rails': 3.5, 'rails': 3., '.rb': 4.5, '/lib': .5,
    'elsif': 4.5,
}
ITERATORS = {'.each', '.map', '.collect', '.times', '.upto', '.downto'}
DISTINCTIVE_METHODS = {'.nil', '.gsub', '.dup'}
FOREIGN = {'php', '<?php', 'const', 'function', 'import', 'namespace',
           'public', 'protected', '#include', 'package',
           '.py', '.js', '.ts', '.rs', '.go', '.java', '.cpp', '.cs', '.c'}


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 0., '', '', None, False)
    _, ruby, line, previous, quote, comment = carry
    ruby *= .997
    t = s.strip()
    if previous == '.' and t.isidentifier():
        t = '.' + t
    header = line + s.split('\n')[0]
    inheritance = (
        t == '<' and s.startswith(' ') and ruby >= 0
        and bool(re.fullmatch(r'\s*class\s+\w+\s*', line))
    )
    require_quote = previous in {'require', '_relative'} and t.startswith(('"', "'"))
    accessor = previous == 'attr' and t in {'_reader', '_writer', '_accessor'}
    relative = previous == 'require' and t == '_relative'
    header_end = '\n' in s and bool(re.match(r'\s*(class|module|def)\s+\w+', header))
    header_end = header_end and not any(c in header for c in ':{};')
    if t in {'<|im_start|>', '<|im_end|>'}:
        ruby, quote, comment = 0., None, False
    python_header = re.match(r'\s*(?:\d+:)?(?:def|class)\b', header)
    if '\n' in s and python_header and header.rstrip().endswith(':'):
        ruby = -1.
    if t in FOREIGN:
        ruby = -1.
    if relative or accessor or (t == 'ruby' and previous.endswith('`')):
        ruby = 1.
    if ruby >= 0:
        if require_quote or inheritance:
            ruby = 1.
        if t in {'.each', '.nil', '.gsub', 'elsif', '.rb'}:
            ruby = max(ruby, .65)
        if header_end:
            ruby = max(ruby, .85)
        if t == 'do' and ('.each' in line or re.match(r'\s*(it|describe)\s', line)):
            ruby = 1.
        if t == 'eq' and previous in {'.to', '.should', 'to'}:
            ruby = max(ruby, .95)
        if t.startswith('?(') and re.match(r'\s*def\s', line):
            ruby = max(ruby, .85)
        if t == 'puts' and not line.strip():
            ruby = max(ruby, .8)
    confidence = max(0., ruby) if not quote and not comment else 0.
    base, extra = BASE.get(t, 0.), KEYWORDS.get(t, .15)
    if relative:
        base, extra = 11.5, 0.
    elif accessor:
        base, extra = 7.5, 0.
    elif require_quote:
        base, extra = (8., 0.) if ruby >= 0 else (2., 0.)
    elif inheritance:
        base, extra = 9.4, 0.
    elif '#{' in t:
        base, extra = 3.7, 0.
    elif t in {'||=', '&&=', '=~', '!~'}:
        base, extra = 4.8, 0.
    elif t == '.new':
        extra = 8.1
    elif t in ITERATORS:
        extra = 4.9
    elif t in DISTINCTIVE_METHODS:
        base, extra = 1.2, 4.
    elif t in {'.include', '.respond', '.to'}:
        extra = 5.8
    elif t == '.should':
        base, extra = .4, 3.7
    elif t == '.have':
        base, extra = 1.7, 1.
    elif t == '.key' and previous == '.have':
        base, extra = .85, 0.
    elif t in {'eq', '.eq', 'expect', 'describe'}:
        extra = 3.7
    elif t in {'_s', '_i', '_f', '_sym', '_method'}:
        extra = 5.8
    elif t == '.class':
        extra = 5.2
    elif t.startswith('?') and not s[0].isspace():
        base, extra = -.06, 8.2
    elif t == '!':
        extra = 5.
    elif t == '::':
        extra = 6.8
    elif t == '=>':
        extra = 3.7
    elif '|' in t and all(c in '|{}' for c in t):
        extra = 4.6
    elif t in {'||', '&&', '<<'}:
        extra = 2.8
    elif t.startswith('@'):
        extra = 1.6
    elif ':' in t and all(c in ':[](' for c in t):
        extra = 1.4
    elif '=' in t and all(c in '=+-*/' for c in t):
        extra = 1.
    elif t in {'"', "'"}:
        extra = .7
    elif header_end:
        extra = 5.7 if re.match(r'\s*def\s', header) else 3.
    elif not t:
        extra = 1.2 if '\n' in s else .85
    elif t.startswith('.') and t[1:].isidentifier():
        extra = 1.1
    elif t.isidentifier() and t not in KEYWORDS:
        extra = .1
    value = base + confidence * extra - (.16 if first else 0.)
    # Only the current line and quote/comment status are carried forward.
    for ch in s:
        if ch == '\n':
            line, quote, comment = '', None, False
            continue
        line = (line + ch)[-180:]
        if comment:
            continue
        if quote:
            if ch == quote and not line[:-1].endswith('\\'):
                quote = None
        elif ch in "\"'":
            quote = ch
        elif ch == '#':
            comment = True
    if '```' in s:
        ruby = 0.
    return (doc, ruby, line, t, quote, comment), float(value)

programs.haiku:
"""Ruby idioms, plus document starts. Two things, both read from the text so far:
(1) Tokens typical of Ruby code (Ruby method names, string interpolation, Rails and RSpec
calls) get a positive activation, larger once the document has shown Ruby context (a Ruby or
Rails word, a def/end block, require, .each, puts or a .rb file).
(2) The first token of each document (where attention can only see itself) gets a negative
activation that depends on its kind: digits most, words and capitals about -0.2, punctuation
little, whitespace none."""
import re

RUBY_CONTEXT = re.compile(r"(?:Ruby|ruby|Rails|rails|Gem|gem|Struct|def |\bend\n|\.each|require|puts|\.rb)")
STRONG = {"?(", "puts", "_relative", " #{", " Rails", "Struct", ".new"}
RSPEC = {".have", ".include", ".should", " eq", ".to", ".nil"}
MISC = {" Ruby", " ruby", "gem", " Gem", ".each", "{|", "\tend", " initialize", "require", "validates", "(:", "[:", "%=", "<%=", ".rb"}

READS = ()

def start_value(tok):
    t = tok.strip()
    if t == "":
        return 0.0
    if t[0].isdigit():
        return -0.3
    if all(not c.isalnum() for c in t):
        return -0.05
    return -0.2

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        text, ruby = "", False
        first = True
    else:
        text, ruby = carry[1], carry[2]
        first = False
    if first:
        value = start_value(tok)
    else:
        value = 0.0
        if tok in STRONG:
            value = 3.5 if ruby else 1.0
        elif tok in RSPEC:
            value = 2.3 if ruby else 0.8
        elif tok in MISC:
            value = 0.9 if ruby else 0.6
    text = (text + tok)[-200:]
    ruby = ruby or bool(RUBY_CONTEXT.search(text))
    return (doc, text, ruby), value

programs.sol:
"""A multilingual verb-morphology approximation.

The main positive response is to a continuation of a conjugated verb,
especially a finite Romance verb. Generate candidate spellings from common
infinitives and conjugation rules, not from model token identities. Recent
word frequencies choose a likely language. Longer verbal stems, a/e endings,
and relative-clause cues strengthen the response; English lookalikes and
noun-like contexts weaken it. Also predict a negative document-start offset.
This is deliberately a partial morphology recognizer, not a full parser.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()

# Infinitive endings and a selection of common conjugated endings.
CONJUGATIONS = {
    'pt': [
        ('ar', 'o a as am ava ando ado aram ei ou aste avam aria arias '
               'ariam arei ara aras arão e es em emos ada adas ados '),
        ('er', 'o e es em eu ia endo ido eram i este iam eria eriam erei '
               'era eras erão a as am amos ida idas idos '),
        ('ir', 'o e es em iu ia indo ido iram i iste iam iria iriam irei '
               'ira iras irão a as am amos ida idas idos '),
    ],
    'es': [
        ('ar', 'o a as an aba ando ado aron ó é aban amos e es en ada '
               'adas ados '),
        ('er', 'o e es en ia iendo ido ieron ió í ian emos imos a as an '
               'ida idas idos '),
        ('ir', 'o e es en ia iendo ido ieron ió í ian emos imos a as an '
               'ida idas idos '),
    ],
    'it': [
        ('are', 'o a i ano ava ando ato ava avano ai ò atto ata ate ati '),
        ('ere', 'o e i ono eva endo uto evo eva evano uto uta uti ute '),
        ('ire', 'o e i ono iva endo ito iva ivano isco isce iscono ita iti '
               'ite '),
    ],
    'fr': [
        ('er', 'e es ent ons ez ait ais ant é aient ée ées és erai era '
               'eront erait erais '),
        ('ir', 'is it issent issons issait i '),
        ('re', 's d ent ons ez ait ais ant u '),
    ],
    'ru': [
        ('ать', 'аю ает ают ал ала али ай айте ая ающ '),
        ('ять', 'яю яет яют ял яла яли яй яйте яя яющ '),
        ('ить', 'ю ит ят им ите ил или ив и '),
        ('еть', 'ю ит ят им ите ел ели еть я '),
        ('овать', 'ую ует уют овал овали уй уйте '),
    ],
    'pl': [
        ('ać', 'am a ają ał ała ali ając '),
        ('ować', 'uję uje ują ował owali '),
        ('ić', 'ię i isz ią ił ili '),
        ('yć', 'yję yje yją ył yli '),
    ],
    'cs': [
        ('at', 'á ám áš ají al ali at '),
        ('ovat', 'uje ují oval ovali ování '),
        ('it', 'í ím íš il ili íte '),
    ],
    'de': [
        ('en', 'e st t te ten end '),
    ],
}
LANGUAGES = tuple(CONJUGATIONS) + ('en',)
PARTICIPLE_LIKE = frozenset("""
ando endo indo ado ada ados adas ido ida idos idas ato ata ati ate
uto uta uti ute ito ita iti ite ant é ée és ées ающ яющ end ая яя ąc ając
""".split())
RELATIVE_WORDS = frozenset('que qui che dass что как'.split())
NOUN_CUES = frozenset("""
un une du una unos unas um uma uns umas il uno dei delle della del
 de da do dos das para pour por di con avec sur en em a à
""".split())


def altered_stems(stem, language, suffix):
    """Common spelling changes, accepted only if the resulting word exists."""
    yield stem
    if language in ('pt', 'es') and suffix[:1] in 'ei':
        for old, new in [('c', 'qu'), ('g', 'gu'), ('ç', 'c')]:
            if stem.endswith(old):
                yield stem[:-1] + new
    if language in ('pt', 'es') and suffix[:1] in 'ao':
        if stem.endswith('g'):
            yield stem[:-1] + 'j'
        if stem.endswith('c'):
            yield stem[:-1] + ('ç' if language == 'pt' else 'zc')
    if language == 'es':
        for old, new in [('e', 'ie'), ('o', 'ue'), ('e', 'i')]:
            i = stem.rfind(old)
            if i >= 0:
                yield stem[:i] + new + stem[i+1:]
    if language == 'fr':
        for old in ('é', 'e'):
            i = stem.rfind(old)
            if i >= 0:
                yield stem[:i] + 'è' + stem[i+1:]
        if stem[-1:] in 'lt':
            yield stem + stem[-1:]


@lru_cache(None)
def lexicon():
    """Keep productive infinitives, their forms, and near-complete stems."""
    result = {}
    for language, classes in CONJUGATIONS.items():
        for infinitive in top_n_list(language, 50000):
            if not infinitive.isalpha() or len(infinitive) < 5:
                continue
            for ending, suffixes in classes:
                if not infinitive.endswith(ending):
                    continue
                stem = infinitive[:-len(ending)]
                suffixes = suffixes.split()
                # Reject nouns that only happen to resemble infinitives.
                common_forms = sum(zipf_frequency(stem+s, language) >= 3
                                   for s in suffixes)
                if common_forms < 3:
                    continue
                infinitive_frequency = zipf_frequency(infinitive, language)
                for suffix in suffixes:
                    finite = suffix not in PARTICIPLE_LIKE
                    for base in altered_stems(stem, language, suffix):
                        word = base + suffix
                        frequency = zipf_frequency(word, language)
                        if frequency < 2.3:
                            continue
                        for n in range(max(3, len(base)-1), len(word)+1):
                            info = (len(base), n == len(word), finite,
                                    frequency, infinitive_frequency)
                            choices = result.setdefault(word[:n], {})
                            old = choices.get(language)
                            if old is None or (info[2], info[1], info[3]) > (
                                    old[2], old[1], old[3]):
                                choices[language] = info
    return result


@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def strength(word, token, language, info, preceding_word):
    stem, full, finite, frequency, infinitive_frequency = info
    offset = dict(pt=0, es=-.05, fr=-.15, it=-.20,
                  ru=-.25, pl=-.28, de=-.67, cs=-.54)[language]
    value = (.33 + offset
             + .07 * max(-3, min(6, stem-5))
             + .20 * (infinitive_frequency-4)
             - .13 * (frequency-4)
             - .18 * (frequencies(word.lower())[-1]-3)
             - .30 * len(token)/len(word)
             - .10 * (min(5, len(word)-stem)-1)
             + .50 * (word[-1:] in 'ae')
             + .44 * (preceding_word in RELATIVE_WORDS)
             - .26 * (preceding_word in NOUN_CUES))
    return max(0., min(3., value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    initial = ('', [0.]*len(LANGUAGES), '')
    previous, context, last_word = initial if first else carry[1:]
    token = prefix.token_strings[-1]
    continuation = bool(previous and token.isalpha())
    if token.isalpha():
        word = (previous + token)[-40:]
    else:
        closed = ([previous] if previous else [])
        closed += re.findall(r'[^\W\d_]+', token)[:-1]
        for w in closed:
            last_word = w.lower()
            context = [.8*a+b for a, b in zip(context, frequencies(last_word))]
        match = re.search(r'[^\W\d_]+$', token)
        word = match.group() if match else ''
    state = (doc, word, context, last_word)
    if first:
        if token.isalpha():
            return state, -.46 if len(token) == 1 else -.59
        if token.strip().isalpha():
            return state, -.17
        return state, -.08 if len(token) == 1 else -.23

    choices = lexicon().get(word.lower(), {})
    if not choices:
        return state, 0.
    language = max(choices, key=lambda l: context[LANGUAGES.index(l)])
    info = choices[language]
    stem, full, finite, frequency, infinitive_frequency = info
    supported = context[LANGUAGES.index(language)] > context[-1] + 1
    if not supported:
        return state, .04 if continuation and full and finite else 0.
    if continuation and len(word) > stem:
        if not finite:
            return state, .08
        if full:
            return state, strength(word, token, language, info, last_word)
        return state, .04 if language == 'de' else .4
    if continuation and finite:
        return state, dict(pt=.24, es=.26, fr=.10, it=.18).get(language, 0.)
    if full and finite:
        return state, .16 if language == 'fr' else .08
    return state, -.085 if language == 'ru' and len(word) <= stem else 0.
